import {
  Controller,
  Post,
  Get,
  Body,
  HttpCode,
  HttpStatus,
  UseGuards,
  Req,
  Res,
  BadRequestException,
} from '@nestjs/common';
import { Response } from 'express';
import { AuthGuard } from '@nestjs/passport';
import { ApiTags, ApiOperation } from '@nestjs/swagger';
import { IsEmail, IsString, MinLength } from 'class-validator';
import { ApiProperty } from '@nestjs/swagger';
import { AuthService } from './auth.service';
import {
  RegisterDto,
  LoginDto,
  RefreshTokenDto,
  ExchangeCodeDto,
} from './dto/auth.dto';

// ── Cookie configuration ───────────────────────────────────────────────────────

const COOKIE_NAME_ACCESS = 'accessToken';
const COOKIE_NAME_REFRESH = 'refreshToken';

const isProd = process.env.NODE_ENV === 'production';

/** Cookie options shared across login/register/refresh */
const cookieOptions = (maxAgeSec: number) => ({
  httpOnly: true,
  secure: isProd, // HTTPS only in production
  sameSite: 'lax' as const,
  domain: isProd ? '.nglob.com' : undefined,
  path: '/',
  maxAge: maxAgeSec * 1000, // express uses milliseconds
});

/** Clear-cookie options (must match the options used to set them) */
const clearOptions = {
  httpOnly: true,
  secure: isProd,
  sameSite: 'lax' as const,
  domain: isProd ? '.nglob.com' : undefined,
  path: '/',
};

// ── OAuth redirect allowlist ───────────────────────────────────────────────────

const ALLOWED_REDIRECT_PATTERNS = [
  /^https:\/\/([\w-]+\.)?nglob\.com(\/.*)?$/,
  /^http:\/\/([\w-]+\.)?localhost(:\d+)?(\/.*)?$/,
  /^http:\/\/([\w-]+\.)?nglob\.local(:\d+)?(\/.*)?$/,
];

function isAllowedRedirect(uri: string): boolean {
  try {
    return ALLOWED_REDIRECT_PATTERNS.some((pattern) => pattern.test(uri));
  } catch {
    return false;
  }
}

// ── Password reset DTOs (inline — no separate file needed) ────────────────────

class ForgotPasswordDto {
  @ApiProperty({ example: 'jane@example.com' })
  @IsEmail()
  email: string;
}

class ResetPasswordDto {
  @ApiProperty({ example: 'abc123xyz...' })
  @IsString()
  token: string;

  @ApiProperty({ example: 'NewSecurePass123!' })
  @IsString()
  @MinLength(8)
  newPassword: string;
}

// ── Controller ────────────────────────────────────────────────────────────────

@ApiTags('Auth')
@Controller('auth')
export class AuthController {
  constructor(private authService: AuthService) {}

  @Post('register')
  @ApiOperation({ summary: 'Register new customer account' })
  async register(
    @Body() dto: RegisterDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.register(dto);
    this.setAuthCookies(res, result.accessToken, result.refreshToken);
    return result;
  }

  @Post('login')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Login and get JWT tokens (also sets HttpOnly cookies)',
  })
  async login(
    @Body() dto: LoginDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.login(dto);
    this.setAuthCookies(res, result.accessToken, result.refreshToken);
    return result;
  }

  @Post('refresh')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Rotate refresh token and get new access token' })
  async refresh(
    @Body() dto: RefreshTokenDto,
    @Res({ passthrough: true }) res: Response,
    @Req() req: any,
  ) {
    // Accept refresh token from body or cookie
    const tokenToUse = dto.refreshToken || req.cookies?.[COOKIE_NAME_REFRESH];
    if (!tokenToUse) throw new BadRequestException('Refresh token is required');

    const result = await this.authService.refreshToken(tokenToUse);
    this.setAuthCookies(res, result.accessToken, result.refreshToken);
    return result;
  }

  @Post('logout')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary:
      'Invalidate refresh token and clear auth cookies on all subdomains',
  })
  async logout(
    @Body() dto: RefreshTokenDto,
    @Req() req: any,
    @Res({ passthrough: true }) res: Response,
  ) {
    const tokenToRevoke =
      dto.refreshToken || req.cookies?.[COOKIE_NAME_REFRESH];
    if (tokenToRevoke) {
      await this.authService.logout(tokenToRevoke);
    }
    // Clear cookies on all subdomains (domain=.nglob.com in prod)
    res.clearCookie(COOKIE_NAME_ACCESS, clearOptions);
    res.clearCookie(COOKIE_NAME_REFRESH, clearOptions);
    return { success: true };
  }

  @Post('forgot-password')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Request a password reset link (logged to console in dev)' })
  async forgotPassword(@Body() dto: ForgotPasswordDto) {
    return this.authService.forgotPassword(dto.email);
  }

  @Post('reset-password')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Reset password using a token from the reset link' })
  async resetPassword(
    @Body() dto: ResetPasswordDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.resetPassword(dto.token, dto.newPassword);
    // Clear auth cookies so user must log in fresh after reset
    res.clearCookie(COOKIE_NAME_ACCESS, clearOptions);
    res.clearCookie(COOKIE_NAME_REFRESH, clearOptions);
    return result;
  }

  // ── OAuth Code Exchange ──────────────────────────────────────────────────────

  @Post('exchange-code')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Exchange short-lived OAuth code for JWT tokens' })
  async exchangeCode(
    @Body() dto: ExchangeCodeDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.exchangeAuthCode(dto.code);
    this.setAuthCookies(res, result.accessToken, result.refreshToken);
    return result;
  }

  // ── OAuth Routes ─────────────────────────────────────────────────────────────

  @Get('google')
  @UseGuards(AuthGuard('google'))
  async googleAuth(@Req() req) {
    // triggers passport strategy
  }

  @Get('callback/google')
  @UseGuards(AuthGuard('google'))
  async googleAuthRedirect(@Req() req, @Res() res: Response) {
    const tokens = await this.authService.validateOAuthLogin(req.user);
    const code = this.authService.createAuthCode(tokens);
    const redirect = this.buildOAuthRedirectUrl(code, req.query?.state);
    res.redirect(redirect);
  }

  @Get('facebook')
  @UseGuards(AuthGuard('facebook'))
  async facebookAuth(@Req() req) {}

  @Get('callback/facebook')
  @UseGuards(AuthGuard('facebook'))
  async facebookAuthRedirect(@Req() req, @Res() res: Response) {
    const tokens = await this.authService.validateOAuthLogin(req.user);
    const code = this.authService.createAuthCode(tokens);
    const redirect = this.buildOAuthRedirectUrl(code, req.query?.state);
    res.redirect(redirect);
  }

  @Get('apple')
  @UseGuards(AuthGuard('apple'))
  async appleAuth(@Req() req) {}

  @Post('callback/apple')
  @UseGuards(AuthGuard('apple'))
  async appleAuthRedirect(@Req() req, @Res() res: Response) {
    const tokens = await this.authService.validateOAuthLogin(req.user);
    const code = this.authService.createAuthCode(tokens);
    const redirect = this.buildOAuthRedirectUrl(code, req.query?.state);
    res.redirect(redirect);
  }

  // ── Helpers ──────────────────────────────────────────────────────────────────

  private setAuthCookies(
    res: Response,
    accessToken: string,
    refreshToken: string,
  ) {
    // Access token: 7 days
    res.cookie(COOKIE_NAME_ACCESS, accessToken, cookieOptions(7 * 24 * 3600));
    // Refresh token: 30 days
    res.cookie(
      COOKIE_NAME_REFRESH,
      refreshToken,
      cookieOptions(30 * 24 * 3600),
    );
  }

  private buildOAuthRedirectUrl(code: string, stateParam?: string): string {
    const defaultFrontend = process.env.FRONTEND_URL || 'http://localhost:3000';
    const callbackPath = '/oauth/callback';

    // If a state param was passed that encodes a redirect URI, validate it
    if (stateParam) {
      try {
        const parsed = JSON.parse(Buffer.from(stateParam, 'base64').toString());
        if (parsed.redirectUri && isAllowedRedirect(parsed.redirectUri)) {
          return `${parsed.redirectUri}${callbackPath}?code=${code}`;
        }
      } catch {
        // Invalid state — fall through to default
      }
    }

    return `${defaultFrontend}${callbackPath}?code=${code}`;
  }
}

import {
  Injectable,
  UnauthorizedException,
  ConflictException,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { PrismaService } from '../prisma/prisma.service';
import { NotificationService } from '../notifications/notification.service';
import * as bcrypt from 'bcryptjs';
import { RegisterDto, LoginDto } from './dto/auth.dto';
import { Role, NotificationType } from '@prisma/client';
import { nanoid } from 'nanoid';
import * as crypto from 'crypto';

@Injectable()
export class AuthService {
  // In-memory store for short-lived OAuth authorization codes
  // Map<code, { accessToken, refreshToken, expiresAt }>
  private authCodes = new Map<
    string,
    { accessToken: string; refreshToken: string; expiresAt: Date }
  >();

  // In-memory store for password reset tokens — 1 hour TTL
  // Map<token, { userId, expiresAt }>
  private passwordResetTokens = new Map<
    string,
    { userId: string; expiresAt: Date }
  >();

  constructor(
    private prisma: PrismaService,
    private jwt: JwtService,
    private notificationService: NotificationService,
  ) {}

  // ── Register ──────────────────────────────────────────────
  async register(dto: RegisterDto) {
    // Check duplicate email
    const existing = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (existing) throw new ConflictException('Email already in use');

    // Handle referral code
    let referredById = null;
    if (dto.referralCode) {
      const referrer = await this.prisma.user.findUnique({
        where: { referralCode: dto.referralCode },
      });
      if (referrer) {
        referredById = referrer.id;
      }
    }

    // Hash password
    const hashed = await bcrypt.hash(dto.password, 12);

    // Create user
    const user = await this.prisma.user.create({
      data: {
        name: dto.name,
        email: dto.email,
        password: hashed,
        phone: dto.phone,
        role: dto.role ? Role[dto.role] : Role.CUSTOMER,
        referralCode: nanoid(8),
        referredById,
      },
    });

    // Notify the referrer that someone just signed up via their link
    if (referredById) {
      await this.notificationService.createNotification(
        referredById,
        NotificationType.SYSTEM,
        '🎉 Someone joined using your link!',
        `${user.name} just signed up using your referral link. You'll earn a reward when they make their first booking!`,
        { type: 'referral_signup', referredUserName: user.name },
      );
    }

    const tokens = await this.generateTokens(user.id, user.email, user.role);
    return { ...tokens, user: this.sanitizeUser(user) };
  }

  // ── Login ─────────────────────────────────────────────────
  async login(dto: LoginDto) {
    const user = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (!user) throw new UnauthorizedException('Invalid credentials');

    // Account was created via OAuth (Google/Apple/Facebook) — no local password
    if (!user.password) {
      const providerName = user.provider
        ? user.provider.charAt(0).toUpperCase() + user.provider.slice(1)
        : 'a social provider';
      throw new UnauthorizedException(
        `This account was created with ${providerName}. Please sign in using the "${providerName}" button instead.`,
      );
    }

    const valid = await bcrypt.compare(dto.password, user.password);
    if (!valid) throw new UnauthorizedException('Invalid credentials');

    const tokens = await this.generateTokens(user.id, user.email, user.role);
    return { ...tokens, user: this.sanitizeUser(user) };
  }

  // ── OAuth Login / Register ────────────────────────────────
  async validateOAuthLogin(profile: {
    email: string;
    name: string;
    provider: string;
    providerId: string;
  }) {
    let user = await this.prisma.user.findUnique({
      where: { email: profile.email },
    });

    if (user) {
      // If user exists but is missing provider link, update it
      if (user.provider !== profile.provider) {
        user = await this.prisma.user.update({
          where: { id: user.id },
          data: { provider: profile.provider, providerId: profile.providerId },
        });
      }
    } else {
      // Create new user via OAuth
      user = await this.prisma.user.create({
        data: {
          email: profile.email,
          name: profile.name,
          provider: profile.provider,
          providerId: profile.providerId,
          referralCode: nanoid(8),
        },
      });
    }

    const tokens = await this.generateTokens(user.id, user.email, user.role);
    return {
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
    };
  }

  // ── OAuth Code Exchange ────────────────────────────────────
  createAuthCode(tokens: {
    accessToken: string;
    refreshToken: string;
  }): string {
    // Clean up expired codes
    const now = new Date();
    for (const [key, value] of this.authCodes) {
      if (value.expiresAt < now) this.authCodes.delete(key);
    }

    const code = nanoid(32);
    const expiresAt = new Date(Date.now() + 60 * 1000); // 60-second TTL
    this.authCodes.set(code, { ...tokens, expiresAt });
    return code;
  }

  exchangeAuthCode(code: string): {
    accessToken: string;
    refreshToken: string;
  } {
    const entry = this.authCodes.get(code);
    if (!entry)
      throw new UnauthorizedException('Invalid or expired authorization code');
    if (entry.expiresAt < new Date()) {
      this.authCodes.delete(code);
      throw new UnauthorizedException('Authorization code has expired');
    }
    // Single-use: delete immediately
    this.authCodes.delete(code);
    return { accessToken: entry.accessToken, refreshToken: entry.refreshToken };
  }

  // ── Refresh ───────────────────────────────────────────────
  async refreshToken(refreshToken: string) {
    const hashedToken = crypto.createHash('sha256').update(refreshToken).digest('hex');
    const stored = await this.prisma.refreshToken.findUnique({
      where: { token: hashedToken },
      include: { user: true },
    });

    if (!stored || stored.expiresAt < new Date()) {
      throw new UnauthorizedException('Invalid or expired refresh token');
    }

    // Rotate token
    await this.prisma.refreshToken.delete({ where: { id: stored.id } });

    const tokens = await this.generateTokens(
      stored.user.id,
      stored.user.email,
      stored.user.role,
    );
    return tokens;
  }

  // ── Logout ────────────────────────────────────────────────
  async logout(refreshToken: string) {
    const hashedToken = crypto.createHash('sha256').update(refreshToken).digest('hex');
    await this.prisma.refreshToken.deleteMany({
      where: { token: hashedToken },
    });
    return { success: true };
  }

  // ── Logout all sessions for a user ───────────────────────
  async logoutAllSessions(userId: string) {
    await this.prisma.refreshToken.deleteMany({ where: { userId } });
    return { success: true };
  }

  // ── Forgot Password ───────────────────────────────────────
  async forgotPassword(email: string) {
    // Silently succeed even if no account — prevents email enumeration
    const user = await this.prisma.user.findUnique({ where: { email } });
    if (!user) return { success: true };

    // Clean up expired tokens
    const now = new Date();
    for (const [key, val] of this.passwordResetTokens) {
      if (val.expiresAt < now) this.passwordResetTokens.delete(key);
    }

    // Invalidate any existing reset token for this user
    for (const [key, val] of this.passwordResetTokens) {
      if (val.userId === user.id) this.passwordResetTokens.delete(key);
    }

    const token = nanoid(40);
    const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
    this.passwordResetTokens.set(token, { userId: user.id, expiresAt });

    const frontendUrl = process.env.FRONTEND_URL || 'http://localhost:3000';
    const resetUrl = `${frontendUrl}/reset-password?token=${token}`;

    // In production, send an email. For now, log the link.
    console.log(`[PASSWORD RESET] Reset link for ${email}: ${resetUrl}`);

    return { success: true };
  }

  // ── Reset Password ────────────────────────────────────────
  async resetPassword(token: string, newPassword: string) {
    const entry = this.passwordResetTokens.get(token);
    if (!entry) throw new BadRequestException('Invalid or expired reset token');
    if (entry.expiresAt < new Date()) {
      this.passwordResetTokens.delete(token);
      throw new BadRequestException('Reset token has expired');
    }

    const hashed = await bcrypt.hash(newPassword, 12);
    await this.prisma.user.update({
      where: { id: entry.userId },
      data: { password: hashed },
    });

    // Invalidate token and all existing sessions for security
    this.passwordResetTokens.delete(token);
    await this.prisma.refreshToken.deleteMany({ where: { userId: entry.userId } });

    return { success: true };
  }

  // ── Token generation ──────────────────────────────────────
  private async generateTokens(userId: string, email: string, role: Role) {
    const payload = { sub: userId, email, role };

    const accessToken = this.jwt.sign(payload, {
      secret: process.env.JWT_SECRET,
      expiresIn: '7d',
    });

    const refreshToken = this.jwt.sign(payload, {
      secret: process.env.JWT_REFRESH_SECRET,
      expiresIn: '30d',
    });

    // Store hashed refresh token
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 30);

    const hashedToken = crypto.createHash('sha256').update(refreshToken).digest('hex');
    await this.prisma.refreshToken.create({
      data: {
        token: hashedToken,
        userId,
        expiresAt,
      },
    });

    return { accessToken, refreshToken };
  }

  private sanitizeUser(user: any) {
    const { password, ...rest } = user;
    return rest;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { PrismaService } from '../prisma/prisma.service';
import { AuditService } from '../audit/audit.service';
import { TrackingGateway } from '../tracking/tracking.gateway';

@Injectable()
export class BookingExpiryService {
  private readonly logger = new Logger(BookingExpiryService.name);

  constructor(
    private prisma: PrismaService,
    private audit: AuditService,
    private tracking: TrackingGateway,
  ) {}

  /**
   * Abandoned checkouts: PENDING, unpaid, no invoice, older than 2 hours.
   * Paid jobs are NEVER auto-cancelled.
   */
  @Cron(CronExpression.EVERY_10_MINUTES)
  async cancelAbandonedCarts() {
    const cutoff = new Date(Date.now() - 2 * 60 * 60 * 1000);
    const stale = await this.prisma.booking.findMany({
      where: {
        status: 'PENDING',
        createdAt: { lt: cutoff },
        payments: { none: { status: 'SUCCEEDED' } },
        invoice: { is: null },
      },
      select: { id: true },
    });
    if (stale.length === 0) return;

    const { count } = await this.prisma.booking.updateMany({
      where: { id: { in: stale.map((s) => s.id) }, status: 'PENDING' },
      data: { status: 'CANCELLED' },
    });
    for (const s of stale) {
      await this.audit.logChange(s.id, 'SYSTEM', 'AUTO_CANCELLED', { status: 'PENDING' }, { status: 'CANCELLED', reason: 'Checkout abandoned' });
    }
    this.logger.log(`Cancelled ${count} abandoned carts`);
    this.tracking.broadcastToManagers('dashboard-updated');
  }
}

import { ConflictException } from '@nestjs/common';
import { BookingStatus } from '@prisma/client';

export const VALID_TRANSITIONS: Partial<Record<BookingStatus, BookingStatus[]>> = {
  PENDING:     ['CONFIRMED', 'CANCELLED'],
  CONFIRMED:   ['SCHEDULED', 'CANCELLED'],
  SCHEDULED:   ['ARRIVED', 'LOADED', 'UNREACHABLE', 'CANCELLED'],
  ARRIVED:     ['PACKED', 'LOADED', 'UNREACHABLE', 'CANCELLED'],
  PACKED:      ['LOADED', 'UNREACHABLE', 'CANCELLED'],
  LOADED:      ['IN_TRANSIT', 'UNREACHABLE', 'DELIVERED'],
  IN_TRANSIT:  ['UNLOADING', 'UNREACHABLE', 'DELIVERED'],
  UNLOADING:   ['UNREACHABLE', 'DELIVERED'],
  UNREACHABLE: ['SCHEDULED', 'CONFIRMED', 'CANCELLED'],
  DELIVERED:   [],
  CANCELLED:   [],
};

export const DRIVER_UNDO_MAP: Partial<Record<BookingStatus, BookingStatus>> = {
  ARRIVED:    'SCHEDULED',
  PACKED:     'ARRIVED',
  LOADED:     'PACKED',
  IN_TRANSIT: 'LOADED',
  UNLOADING:  'IN_TRANSIT',
};

export function assertValidTransition(from: BookingStatus, to: BookingStatus): void {
  const allowed = VALID_TRANSITIONS[from] ?? [];
  if (!allowed.includes(to)) {
    throw new ConflictException(
      `Cannot transition booking from ${from} to ${to}. Allowed: [${allowed.join(', ') || 'none'}]`,
    );
  }
}

