import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
  ConflictException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { PricingService } from '../pricing/pricing.service';
import { TrackingGateway } from '../tracking/tracking.gateway';
import { NotificationService } from '../notifications/notification.service';
import { PromoService } from '../promo/promo.service';
import { AuditService } from '../audit/audit.service';
import { BookingStatus, NotificationType } from '@prisma/client';
import { computePaymentState } from '../payments/payment-state.util';
import {
  CreateBookingDto,
  RescheduleBookingDto,
} from './dto/create-booking.dto';
import { UpdateAddressesDto, UpdateItemsDto } from './dto/update-booking.dto';
import { nanoid } from 'nanoid';

// ── Status state machine ───────────────────────────────────────────────────────

import { assertValidTransition } from './booking-state';

// ── UK City detection ──────────────────────────────────────────────────────────

const UK_CITIES = [
  'London',
  'Manchester',
  'Birmingham',
  'Leeds',
  'Glasgow',
  'Edinburgh',
  'Bristol',
  'Liverpool',
  'Sheffield',
  'Cardiff',
  'Belfast',
  'Nottingham',
  'Leicester',
  'Southampton',
  'Newcastle',
  'Brighton',
  'Plymouth',
  'Wolverhampton',
  'Aberdeen',
  'Coventry',
];

// N18: last word-boundary match (city normally comes last in an address; avoid "London Road, Leicester" → London)
function detectCity(address: string): string | null {
  const street = '(?:road|rd|street|st|lane|ln|avenue|ave|close|way|drive|gardens|place)';
  let best: { city: string; idx: number } | null = null;
  for (const city of UK_CITIES) {
    const escaped = city.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp(`\\b${escaped}\\b(?!\\s+${street}\\b)`, 'gi');
    let m: RegExpExecArray | null;
    while ((m = re.exec(address))) {
      if (!best || m.index > best.idx) best = { city, idx: m.index };
    }
  }
  return best?.city ?? null;
}

@Injectable()
export class BookingsService {
  constructor(
    private prisma: PrismaService,
    private pricingService: PricingService,
    private tracking: TrackingGateway,
    private notificationService: NotificationService,
    private audit: AuditService,
    private promoService: PromoService,
  ) {}

  // ── Create booking ────────────────────────────────────────────────────────────
  async create(dto: CreateBookingDto, userId: string) {
    // N28: Enforce minimum storage weeks (1 week per 7 days of storage)
    if (dto.withStorage && dto.storageDays && dto.storageDays > 0) {
      const minWeeks = Math.max(1, Math.ceil(dto.storageDays / 7));
      if (!dto.storageWeeks || dto.storageWeeks < minWeeks) dto.storageWeeks = minWeeks;
    }

    // Calculate pricing — backend geocodes addresses; ignores any client-supplied distanceKm
    let pricing: Awaited<ReturnType<PricingService['calculate']>>;
    try {
      pricing = await this.pricingService.calculateFromAddresses({
        pickupAddress: dto.pickupAddress,
        destinationAddress: dto.destinationAddress,
        pickupLat: dto.pickupLat,
        pickupLng: dto.pickupLng,
        destLat: dto.destLat,
        destLng: dto.destLng,
        homeSize: dto.homeSize,
        moversCount: dto.moversCount,
        extras: dto.extras,
        items: dto.items.map((i) => ({
          volumeM3: (i.widthCm * i.heightCm * i.depthCm) / 1_000_000,
          quantity: i.quantity,
        })),
        packingMaterials: dto.packingMaterials,
        packingTimeHours: dto.packingTimeHours,
        withStorage: dto.withStorage,
        storageSqft: dto.storageSqft,
        storageDays: dto.storageDays,
        storageWeeks: dto.storageWeeks,
        exactPickupTime: dto.exactPickupTime,
        stairsFlights: dto.stairsFlights,
        parkingDistance: dto.parkingDistance,
        packingTier: dto.packingTier,
      });
    } catch (err: any) {
      throw new BadRequestException(
        err.message || 'Unable to calculate pricing for the provided addresses',
      );
    }

    const pricingSettings = await this.pricingService.getSettings();

    let user = await this.prisma.user.findUnique({
      where: { id: userId },
      include: { bookings: { select: { id: true } } },
    });

    let referrerId = user?.referredById;
    let promoDiscountPence = 0;
    let promoCodeId: string | undefined = undefined;

    const isFirstOrder = user?.bookings?.length === 0;

    // Validate and link promo/referral code
    if (dto.promoCode) {
      try {
        const validation = await this.promoService.validate({ code: dto.promoCode, bookingTotal: pricing.totalToPayPence / 100 }, userId);
        promoDiscountPence = Math.round(validation.discountAmount * 100);

        if (validation.kind === 'REFERRAL') {
          const referrerUser = await this.prisma.user.findUnique({ where: { referralCode: validation.code } });
          if (referrerUser && referrerUser.id !== userId && !referrerId && isFirstOrder) {
            user = await this.prisma.user.update({
              where: { id: userId },
              data: { referredById: referrerUser.id },
              include: { bookings: { select: { id: true } } },
            });
            referrerId = referrerUser.id;
          }
        } else {
          const dbPromo = await this.prisma.promoCode.findUnique({ where: { code: validation.code } });
          if (dbPromo) {
            promoCodeId = dbPromo.id;
          }
        }
      } catch (err: any) {
        throw new BadRequestException(err.message || 'Invalid promo code');
      }
    }

    const finalTotalPence = Math.max(
      pricing.totalToPayPence - promoDiscountPence,
      0,
    );
    const finalTotalPrice = finalTotalPence / 100;

    const depositAmount = dto.payDeposit ? pricingSettings.depositAmount : undefined;
    const remainingAmount = dto.payDeposit
      ? Math.max(Math.round((finalTotalPrice - pricingSettings.depositAmount) * 100) / 100, 0)
      : undefined;

    const pickupDate = new Date(dto.pickupDate);
    const remainingDueAt = dto.payDeposit ? new Date(pickupDate) : undefined;

    // R1-10: wrap booking creation + referral reward in a single transaction so
    // that the reward is only credited when the booking actually persists.
    const booking = await this.prisma.$transaction(async (tx) => {
      // R1-17: Generate a unique bookingRef with collision retry. Prefix NGX.
      let bookingRef: string;
      let attempt = 0;
      while (true) {
        attempt++;
        bookingRef = `NGX${nanoid(6).toUpperCase()}`;
        const collision = await tx.booking.findUnique({ where: { bookingRef } });
        if (!collision) break;
        if (attempt > 5) throw new Error('Could not generate a unique booking reference');
      }

      // R1-21: Set to noon UTC so BST dates don't drift to the previous UTC day
      const pickupDateNormalized = (() => { const d = new Date(dto.pickupDate); d.setUTCHours(12, 0, 0, 0); return d; })();

      const newBooking = await tx.booking.create({
        data: {
          bookingRef,
          userId,
          type: dto.type,
          status: BookingStatus.PENDING,
          pickupAddress: dto.pickupAddress,
          destinationAddress: dto.destinationAddress,
          pickupLat: dto.pickupLat,
          pickupLng: dto.pickupLng,
          pickupDate: pickupDateNormalized,
          pickupTimeSlot: dto.exactPickupTime ? 'EXACT' : dto.pickupTimeSlot,
          estimatedDuration: pricing.totalDurationMins,
          homeSize: dto.homeSize,
          moversCount: dto.moversCount,
          extras: dto.extras,
          withStorage: dto.withStorage,
          notesForDriver: dto.notesForDriver,
          packingTimeHours: dto.packingTimeHours,
          exactPickupTime: dto.exactPickupTime,
          stairsFlights: dto.stairsFlights,
          parkingDistance: dto.parkingDistance,
          storageWeeks: dto.storageWeeks,

          // Pricing snapshot — stored in pounds for backwards-compat with Prisma schema
          loadingTimeMins: pricing.loadingTimeMins,
          travelTimeMins: pricing.travelTimeMins,
          baseCost: pricing.baseCost,
          additionalMoverCost: pricing.additionalMoverCost,
          fuelCost: pricing.fuelCost,
          fullPackingCost: pricing.fullPackingCost,
          packingMaterialsCost: pricing.packingMaterialsCost,
          storageCost: pricing.storageCost,
          exactTimeFee: pricing.exactTimeFee,
          stairsFee: pricing.stairsFee,
          parkingFee: pricing.parkingFee,
          totalPrice: finalTotalPrice,
          discountAmount: promoDiscountPence / 100,
          promoCodeId,
          depositAmount,
          remainingAmount,
          remainingDueAt,
          city: detectCity(dto.pickupAddress),
          photoScanUrl: dto.photoScanUrl,

          items: {
            create: dto.items.map((item) => ({
              name: item.name,
              category: item.category,
              widthCm: item.widthCm,
              heightCm: item.heightCm,
              depthCm: item.depthCm,
              volumeM3: (item.widthCm * item.heightCm * item.depthCm) / 1_000_000,
              quantity: item.quantity,
              pricePerUnit: 10, // TODO: replace with catalogue lookup
              isAiScanned: item.isAiScanned || false,
              photoUrl: item.photoUrl || null,
            })),
          },

          packingMaterials: dto.packingMaterials
            ? {
                create: dto.packingMaterials
                  .filter((m) => m.quantity > 0)
                  .map((m) => {
                    let pricePerUnit = 0;
                    if (m.type === 'MEDIUM_BOX')
                      pricePerUnit = pricingSettings.materialMediumBox;
                    else if (m.type === 'LARGE_BOX')
                      pricePerUnit = pricingSettings.materialLargeBox;
                    else if (m.type === 'BUBBLE_WRAP')
                      pricePerUnit = pricingSettings.materialBubbleWrap;
                    else if (m.type === 'PAPER_ROLL')
                      pricePerUnit = pricingSettings.materialPaperRoll;
                    else if (m.type === 'TAPE')
                      pricePerUnit = pricingSettings.materialTape;
                    return { type: m.type, quantity: m.quantity, pricePerUnit };
                  }),
              }
            : undefined,
        },
        include: {
          items: true,
          packingMaterials: true,
        },
      });

      return newBooking;
    });


    // Audit: booking created
    await this.audit.logChange(
      booking.id,
      userId,
      'BOOKING_CREATED',
      {},
      {
        status: BookingStatus.PENDING,
        totalPrice: finalTotalPrice,
        distanceKm: pricing.distanceKm,
      },
    );

    this.tracking.broadcastToManagers('dashboard-updated');

    // R1-12: Automatically create a linked Storage record when withStorage=true
    // Previously the only path to get a Storage row was via POST /storage which
    // the UI (storageOpen) never actually opened.
    if (dto.withStorage && dto.storageSqft) {
      const pricingSettings = await this.pricingService.getSettings();
      const weeklyPrice = Math.round(dto.storageSqft * pricingSettings.storageRatePerSqftPerWeek * 100) / 100;
      const storageRef = `STR${nanoid(6).toUpperCase()}`;
      await this.prisma.storage.upsert({
        where: { bookingId: booking.id },
        create: {
          storageRef,
          userId,
          bookingId: booking.id,
          weeklyPrice,
          deliveryAddress: dto.pickupAddress,
          returnAddress: dto.returnAddress || dto.destinationAddress,
          returnDate: dto.returnDate ? new Date(dto.returnDate) : null,
          returnTimeSlot: (dto.returnTimeSlot as any) || null,
          volumeM3: dto.storageSqft * 0.09290304, // sqft → approximate m³
        },
        update: {}, // already exists — leave as-is
      });
    }

    return { booking, pricing };

  }

  // ── Get all bookings for user ─────────────────────────────────────────────────
  async findAllForUser(userId: string) {
    const bookings = await this.prisma.booking.findMany({
      where: { userId },
      orderBy: { pickupDate: 'desc' },
      include: {
        items: true,
        // R1-1: select only safe public fields — never expose password, email, wallet, debt
        driver: { include: { user: { select: { name: true, phone: true } } } },
        payments: true,
      },
    });

    // Attach computed payment fields to each booking
    const withPaymentState = bookings.map((b) => {
      const { paymentState, amountPaid, amountDue } = computePaymentState(
        b.payments,
        b.totalPrice,
      );

      // Exclude LongText columns (base64 signatures, photos) from list responses
      // to avoid large payloads. Use findOne() to get those fields on demand.
      const { customerSignature, photoScanUrl, extraItemPhoto, loadProofPhoto, ...restBooking } = b;

      const itemsWithoutPhotos = b.items.map((item) => {
        // @ts-ignore - photoUrl might exist if added to schema later
        const { photoUrl, ...restItem } = item;
        return restItem;
      });

      return { 
        ...restBooking, 
        items: itemsWithoutPhotos,
        paymentState, 
        amountPaid, 
        amountDue 
      };
    });

    return {
      active: withPaymentState.filter((b) =>
        [
          'PENDING',
          'CONFIRMED',
          'SCHEDULED',
          'ARRIVED',
          'PACKED',
          'LOADED',
          'IN_TRANSIT',
          'UNLOADING',
          'UNREACHABLE',
        ].includes(b.status),
      ),
      previous: withPaymentState.filter((b) =>
        ['DELIVERED', 'CANCELLED'].includes(b.status),
      ),
    };
  }

  // ── Get single booking ────────────────────────────────────────────────────────
  async findOne(id: string, userId: string) {
    const booking = await this.prisma.booking.findUnique({
      where: { id },
      include: {
        items: true,
        packingMaterials: true,
        driver: { include: { user: { select: { name: true, phone: true } } } },
        payments: { orderBy: { createdAt: 'asc' } },
        storage: true,
      },
    });

    if (!booking) throw new NotFoundException('Booking not found');
    if (booking.userId !== userId) throw new ForbiddenException();

    // Attach authoritative computed payment fields
    const { paymentState, amountPaid, amountDue } = computePaymentState(
      booking.payments,
      booking.totalPrice,
    );

    return { ...booking, paymentState, amountPaid, amountDue };
  }

  // ── Reschedule ────────────────────────────────────────────────────────────────
  async reschedule(id: string, dto: RescheduleBookingDto, userId: string) {
    const booking = await this.findOne(id, userId);

    // R1-5: Only allow rescheduling paid/confirmed bookings.
    // PENDING (unpaid) bookings must not be promoted to SCHEDULED via reschedule.
    // SCHEDULED bookings must not assert SCHEDULED→SCHEDULED (illegal transition).
    const reschedulableStatuses: BookingStatus[] = [
      BookingStatus.CONFIRMED,
      BookingStatus.SCHEDULED,
      BookingStatus.UNREACHABLE,
    ];
    if (!reschedulableStatuses.includes(booking.status)) {
      throw new ConflictException(
        `Cannot reschedule a booking in ${booking.status} status. ` +
          `Booking must be CONFIRMED, SCHEDULED, or UNREACHABLE.`,
      );
    }

    // R1-21: normalize to noon UTC so a UK BST date doesn't drift to the previous UTC day
    const newDate = (() => { const d = new Date(dto.date); d.setUTCHours(12, 0, 0, 0); return d; })();
    const daysUntil = (booking.pickupDate.getTime() - Date.now()) / 86_400_000;
    const pricingSettings = await this.pricingService.getSettings();
    const rescheduleFee = daysUntil < 3 ? pricingSettings.rescheduleFee : 0;

    // Preserve the existing status — do not forcibly set to SCHEDULED
    const updated = await this.prisma.booking.update({
      where: { id },
      data: {
        pickupDate: newDate,
        pickupTimeSlot: dto.timeSlot as any,
        // Keep current status: a CONFIRMED booking stays CONFIRMED,
        // a SCHEDULED booking stays SCHEDULED, etc.
      },
    });

    await this.audit.logChange(
      id,
      userId,
      'RESCHEDULED',
      { date: booking.pickupDate, time: booking.pickupTimeSlot },
      { date: newDate, time: dto.timeSlot, fee: rescheduleFee },
    );

    // N24: notify driver and managers on reschedule
    this.tracking.broadcastToManagers('dashboard-updated');
    if (updated.driverId) this.tracking.broadcastToDriver(updated.driverId, 'assignments-updated');

    return { booking: updated, rescheduleFee };
  }

  // ── Cancel ────────────────────────────────────────────────────────────────────
  async cancel(id: string, userId: string) {
    const booking = await this.findOne(id, userId);

    assertValidTransition(booking.status, BookingStatus.CANCELLED);

    const daysUntil = (booking.pickupDate.getTime() - Date.now()) / 86_400_000;
    const pricingSettings = await this.pricingService.getSettings();
    let cancellationFee = 0;
    if (daysUntil < 7) {
      const percentageCut = Math.round(booking.totalPrice * (pricingSettings.cancellationFeePercent / 100) * 100) / 100;
      cancellationFee = Math.max(percentageCut, pricingSettings.cancellationFeeBase);
    }

    const updated = await this.prisma.booking.update({
      where: { id },
      data: { status: BookingStatus.CANCELLED },
    });

    await this.audit.logChange(
      id,
      userId,
      'ORDER_CANCELLED',
      { status: booking.status },
      {
        status: BookingStatus.CANCELLED,
        fee: cancellationFee,
        reason: 'Customer cancelled',
      },
    );

    this.tracking.broadcastToManagers('dashboard-updated');
    if (updated.driverId) {
      this.tracking.broadcastToDriver(updated.driverId, 'assignments-updated');
    }

    return { booking: updated, cancellationFee };
  }

  // ── Update addresses ──────────────────────────────────────────────────────────
  async updateAddresses(id: string, dto: UpdateAddressesDto, userId: string) {
    const booking = await this.findOne(id, userId);

    if (!['PENDING', 'SCHEDULED'].includes(booking.status)) {
      throw new BadRequestException('Cannot edit a booking in this state');
    }

    const daysUntil = (booking.pickupDate.getTime() - Date.now()) / 86_400_000;
    const pricingSettings = await this.pricingService.getSettings();
    const editFee = daysUntil < 3 ? pricingSettings.rescheduleFee : 0;

    const updated = await this.prisma.booking.update({
      where: { id },
      data: {
        ...(dto.pickupAddress && { pickupAddress: dto.pickupAddress }),
        ...(dto.destinationAddress && {
          destinationAddress: dto.destinationAddress,
        }),
        ...(dto.notesForDriver !== undefined && {
          notesForDriver: dto.notesForDriver,
        }),
        ...(editFee > 0 ? { totalPrice: { increment: editFee } } : {})
      },
    });

    await this.audit.logChange(
      id,
      userId,
      'ADDRESS_UPDATED',
      {
        pickup: booking.pickupAddress,
        destination: booking.destinationAddress,
        notes: booking.notesForDriver,
      },
      {
        pickup: updated.pickupAddress,
        destination: updated.destinationAddress,
        notes: updated.notesForDriver,
        fee: editFee,
      },
    );

    this.tracking.broadcastToManagers('dashboard-updated');
    if (updated.driverId) {
      this.tracking.broadcastToDriver(updated.driverId, 'assignments-updated');
    }

    return { booking: updated, editFee };
  }

  // ── Update items ──────────────────────────────────────────────────────────────
  async updateItems(id: string, dto: UpdateItemsDto, userId: string) {
    const booking = await this.findOne(id, userId);

    if (!['PENDING', 'SCHEDULED'].includes(booking.status)) {
      throw new BadRequestException('Cannot edit items in this state');
    }

    const daysUntil = (booking.pickupDate.getTime() - Date.now()) / 86_400_000;
    const pricingSettings = await this.pricingService.getSettings();
    const editFee = daysUntil < 3 ? pricingSettings.rescheduleFee : 0;

    const newItemsData = dto.items.map((item) => ({
      name: item.name,
      category: item.category,
      widthCm: item.widthCm,
      heightCm: item.heightCm,
      depthCm: item.depthCm,
      volumeM3: (item.widthCm * item.heightCm * item.depthCm) / 1_000_000,
      quantity: item.quantity,
      pricePerUnit: 10,
      isAiScanned: item.isAiScanned || false,
      photoUrl: item.photoUrl || null,
    }));

    const updated = await this.prisma.$transaction(async (tx) => {
      await tx.bookingItem.deleteMany({ where: { bookingId: id } });
      return tx.booking.update({
        where: { id },
        data: {
          items: { create: newItemsData },
          ...(editFee > 0 ? { totalPrice: { increment: editFee } } : {})
        },
        include: { items: true },
      });
    });

    const aiScannedCount = dto.items.filter((i) => i.isAiScanned).length;
    await this.audit.logChange(
      id,
      userId,
      'ITEMS_UPDATED',
      { items: booking.items.length },
      {
        items: updated.items.length,
        fee: editFee,
        aiScannedItems: aiScannedCount,
      },
    );

    this.tracking.broadcastToManagers('dashboard-updated');
    if (updated.driverId) {
      this.tracking.broadcastToDriver(updated.driverId, 'assignments-updated');
    }

    return { booking: updated, editFee };
  }

  // ── Get tracking (last known driver position) ─────────────────────────────────
  async getTracking(id: string, userId: string) {
    const booking = await this.findOne(id, userId);
    if (!booking.driver) {
      return { status: booking.status, driverAssigned: false };
    }

    // R1-6: use the correct schema field name (locationUpdatedAt, not lastLocationAt)
    const TWO_MINUTES_MS = 2 * 60 * 1000;
    const locationUpdatedAt = (booking.driver as any).locationUpdatedAt;
    const isOnline = locationUpdatedAt
      ? Date.now() - new Date(locationUpdatedAt).getTime() < TWO_MINUTES_MS
      : false;

    return {
      status: booking.status,
      driverAssigned: true,
      driverName: booking.driver.user.name,
      driverLat: isOnline ? booking.driver.currentLat : null,
      driverLng: isOnline ? booking.driver.currentLng : null,
      driverOnline: isOnline,
    };
  }

  // ── Confirm payment (called by PaymentsService via Stripe webhook) ────────────
  async confirmPayment(bookingId: string, isDeposit: boolean) {
    const booking = await this.prisma.booking.findUnique({
      where: { id: bookingId },
      include: { user: true, promoCode: true },
    });
    if (!booking) throw new NotFoundException('Booking not found for payment confirmation');

    // N7: Only the first successful payment moves PENDING → CONFIRMED.
    // Webhook retries and the second (remaining-balance) payment find CONFIRMED and exit.
    const moved = await this.prisma.booking.updateMany({
      where: { id: bookingId, status: BookingStatus.PENDING },
      data: { status: BookingStatus.CONFIRMED, ...(isDeposit ? { depositPaidAt: new Date() } : {}) },
    });
    if (moved.count === 0) return booking;

    const pricingSettings = await this.pricingService.getSettings();

    // ── Referral reward (once per new customer) ──────────────
    const referrerId = booking.user?.referredById;
    if (referrerId) {
      const earlier = await this.prisma.booking.count({
        where: { userId: booking.userId, id: { not: booking.id }, status: { notIn: ['PENDING', 'CANCELLED'] } },
      });
      if (earlier === 0) {
        const successfulReferrals = await this.prisma.user.count({
          where: { referredById: referrerId, bookings: { some: { status: { notIn: ['PENDING', 'CANCELLED'] } } } },
        });
        let reward = pricingSettings.referralTier1Reward;
        if (successfulReferrals >= pricingSettings.referralTier3Count) reward = pricingSettings.referralTier3Reward;
        else if (successfulReferrals >= pricingSettings.referralTier2Count) reward = pricingSettings.referralTier2Reward;

        await this.prisma.$transaction([
          this.prisma.user.update({ where: { id: referrerId }, data: { walletBalance: { increment: reward } } }),
          this.prisma.bonusHistory.create({
            data: { userId: referrerId, amount: reward, action: `Referral reward — ${booking.user!.name || 'A user'} booked their first move (${booking.bookingRef})` },
          }),
        ]);
        await this.notificationService.createNotification(
          referrerId, NotificationType.SYSTEM, '💰 You earned a referral reward!',
          `${booking.user!.name || 'A user'} just made their first booking using your code! £${reward} has been added to your wallet.`,
          { type: 'referral_reward', amount: reward, referredUserName: booking.user!.name || 'A user' },
        );
      }
    }

    await this.audit.logChange(
      bookingId, 'SYSTEM', 'PAYMENT_CONFIRMED',
      { status: BookingStatus.PENDING },
      { status: BookingStatus.CONFIRMED, isDeposit },
    );

    // ── Promo usage (once) ────────────────────────────────────
    if (booking.promoCode) {
      await this.promoService
        .applyToBooking(booking.promoCode.code, booking.id, booking.userId)
        .catch((err) => console.error(`Failed to apply promo usage for ${booking.id}: ${err.message}`));
    }

    this.tracking.broadcastToManagers('dashboard-updated');
    return this.prisma.booking.findUniqueOrThrow({ where: { id: bookingId } });
  }

  // ── Pay by Invoice (BUSINESS only) ───────────────────────────────────────────
  async payByInvoice(id: string, userId: string) {
    const booking = await this.findOne(id, userId);

    if (booking.status !== BookingStatus.PENDING) {
      throw new BadRequestException(
        'Booking must be in PENDING state to pay by invoice',
      );
    }

    assertValidTransition(booking.status, BookingStatus.CONFIRMED);

    // Set due date to 30 days from now (Net 30)
    const dueDate = new Date();
    dueDate.setDate(dueDate.getDate() + 30);

    await this.prisma.invoice.create({
      data: {
        userId,
        bookingId: id,
        amount: booking.totalPrice,
        dueDate,
      },
    });

    // M1 fix: payByInvoice sets CONFIRMED (not SCHEDULED) so the booking
    // appears in the manager Dispatch tab awaiting driver assignment.
    // SCHEDULED is only set by assignDriver().
    const updated = await this.prisma.booking.update({
      where: { id },
      data: { status: BookingStatus.CONFIRMED },
    });

    await this.audit.logChange(
      id,
      userId,
      'INVOICE_PAYMENT',
      { status: booking.status },
      { status: BookingStatus.CONFIRMED, method: 'invoice', dueDate },
    );

    this.tracking.broadcastToManagers('dashboard-updated');
    if (updated.driverId) {
      this.tracking.broadcastToDriver(updated.driverId, 'assignments-updated');
    }

    return updated;
  }
}

