// ── Custom validator: destination must differ from pickup ─────────────────────
function NotEqualTo(property: string, validationOptions?: ValidationOptions) {
  return (object: object, propertyName: string) => {
    registerDecorator({
      name: 'notEqualTo',
      target: (object as any).constructor,
      propertyName,
      constraints: [property],
      options: validationOptions,
      validator: {
        validate(value: any, args: ValidationArguments) {
          const [relatedPropertyName] = args.constraints;
          const relatedValue = (args.object as any)[relatedPropertyName];
          if (!value || !relatedValue) return true;
          return (
            value.trim().toLowerCase() !== relatedValue.trim().toLowerCase()
          );
        },
        defaultMessage(args: ValidationArguments) {
          return `${args.property} must not be the same as ${args.constraints[0]}`;
        },
      },
    });
  };
}

export class BookingItemDto {
  @IsString() name: string;
  @IsEnum(ItemCategory) category: ItemCategory;
  @IsNumber() @Min(1) @Max(1500) widthCm: number;
  @IsNumber() @Min(1) @Max(1500) heightCm: number;
  @IsNumber() @Min(1) @Max(1500) depthCm: number;
  @IsNumber() @Min(1) @Max(50) quantity: number;
  @IsOptional() @IsBoolean() isAiScanned?: boolean;
  @IsOptional() @IsString() photoUrl?: string;
}

export class PackingMaterialDto {
  @IsEnum(PackingMaterialType) type: PackingMaterialType;
  @IsNumber() @Min(0) @Max(500) quantity: number;
}

export class CreateBookingDto {
  @IsEnum(BookingType) type: BookingType;

  @IsString() pickupAddress: string;

  @IsString()
  @NotEqualTo('pickupAddress', {
    message: 'destinationAddress must differ from pickupAddress',
  })
  destinationAddress: string;

  @IsOptional() @IsNumber() pickupLat?: number;
  @IsOptional() @IsNumber() pickupLng?: number;
  @IsOptional() @IsNumber() destLat?: number;
  @IsOptional() @IsNumber() destLng?: number;

  @IsDateString() pickupDate: string;
  @IsEnum(TimeSlot) pickupTimeSlot: TimeSlot;

  @IsOptional()
  @IsEnum(HomeSize)
  homeSize?: HomeSize;

  @IsNumber()
  @Min(1)
  @Max(8)
  moversCount: number;

  @IsEnum(ExtrasType) extras: ExtrasType;
  @IsBoolean() withStorage: boolean;

  // distanceKm is NO LONGER accepted from the client.
  // The backend calculates it from addresses via Nominatim + OSRM.
  // Field kept as optional so existing clients don't immediately break,
  // but it is ignored in service logic.
  @IsOptional()
  @IsNumber()
  @Min(0)
  distanceKm?: number;

  @IsOptional()
  @IsString()
  notesForDriver?: string;

  @ValidateIf((o) => o.type === BookingType.FEW_ITEMS)
  @IsArray()
  @ArrayMinSize(1, { message: 'At least one item is required' })
  @ValidateNested({ each: true })
  @Type(() => BookingItemDto)
  items: BookingItemDto[];

  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => PackingMaterialDto)
  packingMaterials?: PackingMaterialDto[];

  @IsOptional()
  @IsNumber()
  @Min(0)
  @Max(24)
  packingTimeHours?: number;

  // Deposit option
  @IsOptional()
  @IsBoolean()
  payDeposit?: boolean;

  // Exact time booking
  @IsOptional()
  @IsString()
  exactPickupTime?: string; // e.g. "08:30" — triggers +£60 fee

  // Promo code
  @IsOptional()
  @IsString()
  promoCode?: string;

  // Storage specific — storageSqft required when withStorage = true
  @ValidateIf((o) => o.withStorage === true)
  @IsNumber()
  @Min(10)
  @Max(5000)
  storageSqft?: number;

  @IsOptional()
  @IsNumber()
  @Min(0)
  @Max(365)
  storageDays?: number;

  @IsOptional()
  @IsNumber()
  @Min(0)
  @Max(104)
  storageWeeks?: number;

  @IsOptional()
  @IsNumber()
  @Min(0)
  @Max(20)
  stairsFlights?: number;

  @IsOptional()
  @IsNumber()
  @Min(0)
  parkingDistance?: number;

  @IsOptional()
  @IsString()
  returnAddress?: string; // where to deliver items back

  @IsOptional()
  @IsString()
  returnDate?: string; // ISO date, can be null = "confirm later"

  @IsOptional()
  returnTimeSlot?: string;

  @IsOptional()
  @IsString()
  photoScanUrl?: string;

  @IsOptional() @IsIn(['ESSENTIALS','FULL','PACK_UNPACK']) packingTier?: string;

}

