import { BookingStatus } from '@prisma/client';

// Jobs a driver is physically working on (busy check, tracking, assignments)
export const ACTIVE_BOOKING_STATUSES: BookingStatus[] = [
  'SCHEDULED', 'ARRIVED', 'PACKED', 'LOADED', 'IN_TRANSIT', 'UNLOADING',
];

// Storage geometry: pricing is per sq ft, DB stores m³ (N10/N27)
export const SQFT_TO_M2 = 0.09290304;
export const STORAGE_HEIGHT_M = 2.4;
export const sqftToM3 = (sqft: number) => sqft * SQFT_TO_M2 * STORAGE_HEIGHT_M;
export const m3ToSqft = (m3: number) => m3 / (SQFT_TO_M2 * STORAGE_HEIGHT_M);

import {
  Controller,
  Get,
  Post,
  Put,
  Patch,
  Param,
  Body,
  UseGuards,
  UseInterceptors,
  UploadedFile,
  BadRequestException,
  Res,
} from '@nestjs/common';
import { Response } from 'express';
import { FileInterceptor } from '@nestjs/platform-express';
import {
  ApiTags,
  ApiBearerAuth,
  ApiOperation,
  ApiConsumes,
} from '@nestjs/swagger';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { RolesGuard } from '../auth/guards/roles.guard';
import { Roles } from '../auth/decorators/roles.decorator';
import { CurrentUser } from '../auth/decorators/current-user.decorator';
import { v4 as uuidv4 } from 'uuid';
import { createReadStream, existsSync, mkdirSync, writeFileSync } from 'fs';
import { join } from 'path';
import { Storage } from '@google-cloud/storage';
import {
  DriverService,
