// Using memory storage for GCS upload

@ApiTags('Driver')
@ApiBearerAuth()
@Controller('driver')
export class DriverController {
  constructor(private driverService: DriverService) {}

  // ── Open to any authenticated user ─────────────────────────
  @Post('apply')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({
    summary: 'Apply as a driver — creates a PENDING driver profile',
  })
  apply(@CurrentUser() user: any, @Body() dto: ApplyAsDriverDto) {
    return this.driverService.applyAsDriver(user.id, dto);
  }

  @Get('status')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({
    summary:
      'Get current driver application status (PENDING/APPROVED/REJECTED or null)',
  })
  getStatus(@CurrentUser() user: any) {
    return this.driverService.getDriverStatus(user.id);
  }

  // ── Document management ────────────────────────────────────
  @Get('documents')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'Get all documents for the current driver' })
  getDocuments(@CurrentUser() user: any) {
    return this.driverService.getDocuments(user.id);
  }

  @Post('documents/upload')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({
    summary: 'Save a driver document record (file already uploaded to GCS)',
  })
  uploadDocument(@CurrentUser() user: any, @Body() dto: UploadDocumentDto) {
    return this.driverService.uploadDocument(user.id, dto);
  }

  @Post('documents/submit')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'Submit all documents for manager review' })
  submitDocuments(@CurrentUser() user: any) {
    return this.driverService.submitDocumentsForReview(user.id);
  }

  // ── Generic file upload endpoint ───────────────────────────
  @Post('upload-file')
  @UseInterceptors(
    FileInterceptor('file', {
      limits: { fileSize: 10 * 1024 * 1024 },
    }),
  )
  @ApiConsumes('multipart/form-data')
  @ApiOperation({ summary: 'Upload a file (image/PDF) to GCS and return its URL' })
  async uploadFile(@UploadedFile() file: any) {
    if (!file) throw new BadRequestException('No file provided');

    // Clean original filename
    const safeName = (file.originalname || 'file').replace(/[^a-zA-Z0-9.-]/g, '_');
    const filename = `${Date.now()}-${uuidv4()}-${safeName}`;
    const bucketName = process.env.GCP_STORAGE_BUCKET || 'nglob-storage';

    // 1. Try Google Cloud Storage
    try {
      const storage = process.env.GCP_PROJECT_ID
        ? new Storage({ projectId: process.env.GCP_PROJECT_ID })
        : new Storage();
      const bucket = storage.bucket(bucketName);
      const blob = bucket.file(filename);

      await new Promise((resolve, reject) => {
        const stream = blob.createWriteStream({
          resumable: false,
          contentType: file.mimetype || 'application/octet-stream',
        });
        stream.on('error', (err) => reject(err));
        stream.on('finish', () => resolve(true));
        stream.end(file.buffer);
      });

      // Attempt making public if bucket allows ACLs
      await blob.makePublic().catch(() => {});

      return { url: `https://storage.googleapis.com/${bucketName}/${filename}` };
    } catch (gcsErr: any) {
      console.error(`[UPLOAD] GCS upload to ${bucketName} failed (${gcsErr.message}). Falling back to local static storage.`, gcsErr);

      // 2. Fallback to local static storage (/uploads)
      const uploadsDir = join(process.cwd(), 'uploads');
      if (!existsSync(uploadsDir)) mkdirSync(uploadsDir, { recursive: true });
      writeFileSync(join(uploadsDir, filename), file.buffer);

      const apiUrl = process.env.API_URL || 'https://api.nglob.com/api';
      const cleanApi = apiUrl.replace(/\/+$/, '');
      return { 
        url: `${cleanApi}/driver/files/${filename}`,
        fallbackUrl: `${cleanApi.replace(/\/api$/, '')}/uploads/${filename}`
      };
    }
  }

  // ── Stream uploaded file (works for both GCS and local fallback) ──
  @Get('files/:filename')
  @ApiOperation({ summary: 'Stream an uploaded file from GCS or local fallback storage' })
  async getFile(@Param('filename') filename: string, @Res() res: Response) {
    const safeName = filename.replace(/[^a-zA-Z0-9._-]/g, '');
    const bucketName = process.env.GCP_STORAGE_BUCKET || 'nglob-storage';

    // 1. Try GCS first
    try {
      const storage = process.env.GCP_PROJECT_ID
        ? new Storage({ projectId: process.env.GCP_PROJECT_ID })
        : new Storage();
      const bucket = storage.bucket(bucketName);
      const file = bucket.file(safeName);
      const [exists] = await file.exists();
      if (exists) {
        const [metadata] = await file.getMetadata();
        if (metadata.contentType) {
          res.setHeader('Content-Type', metadata.contentType);
        }
        res.setHeader('Cache-Control', 'public, max-age=86400');
        file.createReadStream().pipe(res);
        return;
      }
    } catch (err: any) {
      console.warn(`[FILES] GCS fetch failed: ${err.message}`);
    }

    // 2. Try local fallback storage
    const localPath = join(process.cwd(), 'uploads', safeName);
    if (existsSync(localPath)) {
      res.setHeader('Cache-Control', 'public, max-age=86400');
      createReadStream(localPath).pipe(res);
      return;
    }

    res.status(404).json({ message: 'File not found', error: 'Not Found', statusCode: 404 });
  }

  // ── Protected — DRIVER role only ───────────────────────────
  @Patch('location')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({
    summary: 'Update driver GPS — broadcasts to all active booking sockets',
  })
  updateLocation(@Body() dto: UpdateLocationDto, @CurrentUser() user: any) {
    return this.driverService.updateLocation(user.id, dto);
  }

  @Get('assignments')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({ summary: "Get today's assigned bookings" })
  getAssignments(@CurrentUser() user: any) {
    return this.driverService.getAssignments(user.id);
  }

  @Get('history')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({ summary: 'Get all finished bookings for history' })
  getHistory(@CurrentUser() user: any) {
    return this.driverService.getHistory(user.id);
  }

  @Patch('assignments/:bookingId/status')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({
    summary: 'Set booking status (LOADED | DELIVERED | UNREACHABLE)',
  })
  updateStatus(
    @Param('bookingId') bookingId: string,
    @Body() body: any,
    @CurrentUser() user: any,
  ) {
    const {
      status,
      truckPhoto,
      customerSignature,
      extraItem,
      extraTimeHours,
      extraTimePayment,
      extraPackingTimeHours,
      extraPackingMaterialsCost,
      ...rest
    } = body;
    return this.driverService.updateBookingStatus(bookingId, status, user.id, {
      truckPhoto,
      customerSignature,
      extraItem,
      extraTimeHours,
      extraTimePayment,
      extraPackingTimeHours,
      extraPackingMaterialsCost,
    });
  }

  // ── Undo booking status ────────────────────────────────────
  @Post('assignments/:bookingId/undo')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({
    summary: 'Undo booking status by one step (X1 fix)',
  })
  undoStatus(
    @Param('bookingId') bookingId: string,
    @CurrentUser() user: any,
  ) {
    return this.driverService.undoBookingStatus(bookingId, user.id);
  }

  // ── Item flagging ──────────────────────────────────────────
  @Patch('assignments/:bookingId/items/:itemId/flag')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({ summary: 'Flag a booking item with a note' })
  flagItem(
    @Param('bookingId') bookingId: string,
    @Param('itemId') itemId: string,
    @Body() body: any,
    @CurrentUser() user: any,
  ) {
    return this.driverService.flagItem(bookingId, itemId, body.note, user.id);
  }

  // ── Availability management ────────────────────────────────
  @Get('availability')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({ summary: 'Get weekly availability schedule' })
  getAvailability(@CurrentUser() user: any) {
    return this.driverService.getAvailability(user.id);
  }

  @Put('availability')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({ summary: 'Set full weekly availability schedule' })
  setAvailability(@CurrentUser() user: any, @Body() dto: SetAvailabilityDto) {
    return this.driverService.setAvailability(user.id, dto.slots);
  }

  @Patch('availability/:day')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('DRIVER')
  @ApiOperation({ summary: 'Toggle a single day on/off' })
  toggleDay(
    @Param('day') day: string,
    @Body() dto: ToggleDayDto,
    @CurrentUser() user: any,
  ) {
    return this.driverService.toggleDayAvailability(
      user.id,
      parseInt(day),
      dto.isActive,
      dto.startTime,
      dto.endTime,
    );
  }
}

