import {
  Injectable,
  NotFoundException,
  ConflictException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { TrackingGateway } from '../tracking/tracking.gateway';
import { AuditService } from '../audit/audit.service';
import { PaymentsService } from '../payments/payments.service';
import {
  BookingStatus,
  DocumentStatus,
  NotificationType,
  PaymentMethod,
} from '@prisma/client';
import { NotificationService } from '../notifications/notification.service';
import { ACTIVE_BOOKING_STATUSES } from '../common/constants';
import { assertValidTransition, DRIVER_UNDO_MAP } from '../bookings/booking-state';
import { computePaymentState } from '../payments/payment-state.util';
import {
  UpdateLocationDto,
  UpdateBookingStatusDto,
  ApplyAsDriverDto,
  UploadDocumentDto,
  SetAvailabilityDto,
  ToggleDayDto,
} from './dto/driver.dto';

export { UpdateLocationDto, UpdateBookingStatusDto, ApplyAsDriverDto, UploadDocumentDto, SetAvailabilityDto, ToggleDayDto };

function normalizePaymentMethod(
  value?: string | null,
): PaymentMethod | undefined {
  if (!value) return undefined;
  const normalized = value.trim().toUpperCase();
  return Object.values(PaymentMethod).includes(normalized as PaymentMethod)
    ? (normalized as PaymentMethod)
    : undefined;
}



// All required document types for a driver (removals-specific)
const REQUIRED_DOCUMENTS = [
  { docType: 'driving_licence',       label: 'UK Driving Licence (photocard)' },
  { docType: 'dvla_check_code',       label: 'DVLA Check Code' },
  { docType: 'right_to_work',         label: 'Right to Work' },
  { docType: 'dbs_certificate',       label: 'DBS Certificate' },
  { docType: 'hire_reward_insurance', label: 'Hire & Reward Insurance' },
  { docType: 'goods_in_transit',      label: 'Goods-in-Transit Insurance' },
  { docType: 'mot_test_certificate',  label: 'MOT Certificate (van)' },
  { docType: 'v5c_logbook',           label: "V5C logbook / New keeper's slip" },
];

@Injectable()
export class DriverService {
  constructor(
    private prisma: PrismaService,
    private tracking: TrackingGateway,
    private notificationService: NotificationService,
    private audit: AuditService,
    private paymentsService: PaymentsService,
  ) {}


  // ── Apply as a driver ──────────────────────────────────────
  async applyAsDriver(userId: string, dto?: ApplyAsDriverDto) {
    // Check if already applied
    const existing = await this.prisma.driver.findUnique({ where: { userId } });
    if (existing)
      throw new ConflictException('You have already applied as a driver');

    // Create driver record only — role stays CUSTOMER until APPROVED by a manager
    const [driver] = await this.prisma.$transaction([
      this.prisma.driver.create({
        data: {
          userId,
          status: 'PENDING',
          licensingAuthority: dto?.licensingAuthority,
          hasVan: dto?.hasVan ?? false,
        },
        include: { user: { select: { name: true, email: true } } },
      }),
      // NOTE: role is intentionally NOT set to DRIVER here.
      // A manager must approve the application before the role is elevated.
    ]);

    // Create all required document placeholders
    await this.prisma.driverDocument.createMany({
      data: REQUIRED_DOCUMENTS.map((doc) => ({
        driverId: driver.id,
        docType: doc.docType,
        label: doc.label,
        status: 'NOT_PROVIDED' as DocumentStatus,
      })),
    });

    return driver;
  }

  // ── Get driver status ──────────────────────────────────────
  async getDriverStatus(userId: string) {
    const driver = await this.prisma.driver.findUnique({
      where: { userId },
      select: { id: true, status: true, isOnline: true, updatedAt: true },
    });
    return driver; // null if not a driver
  }

  // ── Get driver documents ───────────────────────────────────
  async getDocuments(userId: string) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    return this.prisma.driverDocument.findMany({
      where: { driverId: driver.id },
      orderBy: { createdAt: 'asc' },
    });
  }

  // ── Upload a document ──────────────────────────────────────
  async uploadDocument(userId: string, dto: UploadDocumentDto) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    // N20: Validate docType server-side — don't trust client label
    const def = REQUIRED_DOCUMENTS.find((d) => d.docType === dto.docType);
    if (!def) throw new BadRequestException(`Unknown document type: ${dto.docType}`);

    return this.prisma.driverDocument.upsert({
      where: { driverId_docType: { driverId: driver.id, docType: def.docType } },
      update: {
        fileName: dto.fileName,
        fileUrl: dto.fileUrl || null,
        status: 'UPLOADED' as DocumentStatus,
        uploadedAt: new Date(),
        reviewNote: null,
      },
      create: {
        driverId: driver.id,
        docType: def.docType,
        label: def.label,
        fileName: dto.fileName,
        fileUrl: dto.fileUrl || null,
        status: 'UPLOADED' as DocumentStatus,
        uploadedAt: new Date(),
      },
    });
  }

  // ── Submit documents for review ────────────────────────────
  async submitDocumentsForReview(userId: string) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    const docs = await this.prisma.driverDocument.findMany({ where: { driverId: driver.id } });
    const uploadedCount = docs.filter((d) => d.status !== 'NOT_PROVIDED').length;
    if (uploadedCount === 0) {
      throw new ConflictException('You must upload at least one document before submitting');
    }

    // N20: Don't demote an already-approved driver
    if (driver.status !== 'APPROVED') {
      await this.prisma.driver.update({ where: { id: driver.id }, data: { status: 'PENDING' } });
    }

    return { submitted: true, uploadedCount, totalCount: docs.length };
  }

  // ── Update GPS position ───────────────────────────────────
  async updateLocation(userId: string, dto: UpdateLocationDto) {
    const driver = await this.prisma.driver.update({
      where: { userId },
      // R1-6: also write locationUpdatedAt so getTracking can compute isOnline correctly
      data: {
        currentLat: dto.lat,
        currentLng: dto.lng,
        isOnline: true,
        locationUpdatedAt: new Date(),
      },
      include: {
        bookings: {
          where: {
            // R1-6: broadcast for all in-progress statuses, not just SCHEDULED/LOADED
            status: {
              in: ACTIVE_BOOKING_STATUSES,
            },
            pickupDate: { gte: new Date(new Date().setUTCHours(0, 0, 0, 0)) },
          },
          select: { id: true, status: true },
        },
      },
    });

    // Broadcast to all active bookings for this driver
    for (const booking of driver.bookings) {
      this.tracking.broadcastDriverLocation(booking.id, {
        lat: dto.lat,
        lng: dto.lng,
        status: booking.status,
      });
    }

    return { updated: true };
  }

  // ── Get driver assignments ───────────────────────────────
  async getAssignments(userId: string) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);

    const assignments = await this.prisma.booking.findMany({
      where: {
        OR: [
          { driverId: driver.id },
          { crew: { some: { driverId: driver.id } } }
        ],
        AND: [
          {
            OR: [
              { pickupDate: { gte: todayStart } },
              { status: { in: ACTIVE_BOOKING_STATUSES } },
            ]
          }
        ]
      },
      include: {
        items: true,
        user: { select: { name: true, phone: true } },
        storage: { include: { items: true } },
        packingMaterials: true,
      },
      orderBy: { pickupDate: 'asc' },
    });


    // R1-9: auto-cancel is still called here for backward compat; the
    // canonical scheduled job (see app.module) will handle bulk cancellation.
    return assignments.filter((a: any) => a.status !== BookingStatus.CANCELLED);
  }

  // ── Get driver history ───────────────────────────────────
  async getHistory(userId: string) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    const history = await this.prisma.booking.findMany({
      where: {
        driverId: driver.id,
        status: {
          in: [BookingStatus.DELIVERED, BookingStatus.CANCELLED],
        },
      },
      include: {
        items: true,
        user: { select: { name: true, phone: true } },
        storage: { include: { items: true } },
        packingMaterials: true,
      },
      orderBy: { pickupDate: 'desc' },
    });

    return history;
  }

  // ── Update booking status ─────────────────────────────────
  async updateBookingStatus(
    bookingId: string,
    status: BookingStatus,
    userId: string,
    extras?: {
      truckPhoto?: string;
      deliveryPhoto?: string;
      customerSignature?: string;
      extraItem?: { photo?: string; price?: number; paymentMethod?: string } | null;
      extraTimeHours?: number;
      extraTimePayment?: string;
      extraPackingTimeHours?: number;
      extraPackingMaterialsCost?: number;
    },
  ) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    const booking = await this.prisma.booking.findFirst({
      where: { id: bookingId, driverId: driver.id },   // crew cannot change status (N22)
      include: { payments: true, invoice: true },
    });
    if (!booking) throw new NotFoundException('Booking not found');

    assertValidTransition(booking.status, status);

    // ── Server-side gates (N3, N35) ───────────────────────────
    if (status === BookingStatus.LOADED && !extras?.truckPhoto && !booking.loadProofPhoto) {
      throw new BadRequestException('A load photo is required before marking LOADED');
    }
    if (status === BookingStatus.DELIVERED) {
      if (!extras?.customerSignature && !booking.customerSignature) {
        throw new BadRequestException('A customer signature is required before marking DELIVERED');
      }
      const { paymentState } = computePaymentState(booking.payments, booking.totalPrice);
      if (paymentState !== 'PAID' && !booking.invoice) {
        throw new ConflictException(
          `Booking is not fully paid (${paymentState}). Collect the balance or contact the manager.`,
        );
      }
    }

    // ── Build the update ──────────────────────────────────────
    const updateData: any = { status };
    if (status === BookingStatus.ARRIVED && !booking.actualStartTime) {
      updateData.actualStartTime = new Date();
    }
    if (extras?.truckPhoto && !extras.truckPhoto.startsWith('blob:')) updateData.loadProofPhoto = extras.truckPhoto;
    if (extras?.deliveryPhoto && !extras.deliveryPhoto.startsWith('blob:')) updateData.deliveryProofPhoto = extras.deliveryPhoto;
    if (extras?.customerSignature) updateData.customerSignature = extras.customerSignature;

    if (extras?.extraItem) {
      if (extras.extraItem.photo) updateData.extraItemPhoto = extras.extraItem.photo;
      if (extras.extraItem.price != null) updateData.extraItemPrice = extras.extraItem.price;
      const m = normalizePaymentMethod(extras.extraItem.paymentMethod);
      if (m) updateData.extraItemPaymentMethod = m;
    }

    if (extras?.extraTimeHours) {
      const settings = await this.prisma.pricingSettings.findUnique({ where: { id: 'global' } });
      const base = settings?.baseRatePerHour ?? 60;
      const addl = settings?.additionalMoverPerHour ?? 15;
      const movers = booking.moversCount ?? 1;
      const rate = base + (movers > 1 ? addl * (movers - 1) : 0);
      updateData.extraTimeHours = extras.extraTimeHours;
      updateData.extraTimeCost = Math.round(extras.extraTimeHours * rate * 100) / 100;
    }
    const extraTimePayment = normalizePaymentMethod(extras?.extraTimePayment);
    if (extraTimePayment) updateData.extraTimePayment = extraTimePayment;
    if (extras?.extraPackingTimeHours) updateData.extraPackingTimeHours = extras.extraPackingTimeHours;
    if (extras?.extraPackingMaterialsCost) updateData.extraPackingMaterialsCost = extras.extraPackingMaterialsCost;

    // ── Optimistic lock: a second DELIVERED tap updates 0 rows ─
    const { count } = await this.prisma.booking.updateMany({
      where: { id: bookingId, status: booking.status },
      data: updateData,
    });
    if (count === 0) throw new ConflictException('Booking status changed. Refresh and try again.');
    const updated = await this.prisma.booking.findUniqueOrThrow({ where: { id: bookingId } });

    // ── Audit without the base64 blobs (N17) ──────────────────
    const { customerSignature, truckPhoto, deliveryPhoto, ...safeExtras } = extras ?? {};
    await this.audit.logChange(
      bookingId, userId, 'STATUS_CHANGED',
      { status: booking.status },
      {
        status: updated.status,
        extras: { ...safeExtras, hasSignature: !!customerSignature, hasLoadPhoto: !!truckPhoto, hasDeliveryPhoto: !!deliveryPhoto },
      },
    );

    this.tracking.broadcastDriverLocation(bookingId, {
      lat: driver.currentLat!, lng: driver.currentLng!, status: status.toString(),
    });
    this.tracking.broadcastToManagers('dashboard-updated');
    this.tracking.broadcastToDriver(driver.id, 'assignments-updated');

    // ── DELIVERED side effects (atomic; N6) ───────────────────
    if (status === BookingStatus.DELIVERED) {
      const settings = await this.prisma.pricingSettings.findUnique({ where: { id: 'global' } });
      const bonusAmount = settings?.bonusAmount ?? 0.5;
      const customer = await this.prisma.user.findUnique({
        where: { id: updated.userId }, select: { role: true },
      });
      const isBusiness = customer?.role === 'BUSINESS';

      // Debt comes from the STORED row, not the request body (the old code read extras.extraTimeCost, which is never sent)
      const debt = isBusiness ? 0 :
        (updated.extraTimePayment === PaymentMethod.DEBT ? updated.extraTimeCost ?? 0 : 0) +
        (updated.extraItemPaymentMethod === PaymentMethod.DEBT ? updated.extraItemPrice ?? 0 : 0);

      await this.prisma.$transaction(async (tx) => {
        await tx.user.update({
          where: { id: updated.userId },
          data: {
            walletBalance: { increment: bonusAmount },
            ...(debt > 0 ? { outstandingDebt: { increment: debt } } : {}),
          },
        });
        await tx.bonusHistory.create({
          data: { userId: updated.userId, amount: bonusAmount, action: `Move completed — booking ${updated.bookingRef}` },
        });

        if (isBusiness) {
          const notCash = (m?: PaymentMethod | null) => !!m && m !== PaymentMethod.CASH;
          const billable =
            (updated.totalPrice || 0) +
            (notCash(updated.extraTimePayment) ? updated.extraTimeCost || 0 : 0) +
            (notCash(updated.extraItemPaymentMethod) ? updated.extraItemPrice || 0 : 0) +
            (updated.extraPackingMaterialsCost || 0);

          const existing = await tx.invoice.findUnique({ where: { bookingId: updated.id } });
          if (!existing) {
            const dueDate = new Date();
            dueDate.setDate(dueDate.getDate() + 30);
            await tx.invoice.create({
              data: { userId: updated.userId, bookingId: updated.id, amount: billable, status: 'UNPAID', dueDate },
            });
          } else if (existing.status !== 'PAID') {
            await tx.invoice.update({ where: { id: existing.id }, data: { amount: billable } }); // keep original dueDate
          }
        }
      });

      await this.notificationService.createNotification(
        updated.userId, NotificationType.SYSTEM, 'How was your move?',
        'Thank you for choosing NGLOB! We would love to hear about your experience. Please leave us a review on Google.',
        { link: 'https://g.page/r/nglob-removals/review' },
      );
    }

    return updated;
  }

  // ── Availability ───────────────────────────────────────────
  async getAvailability(userId: string) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    const slots = await this.prisma.driverAvailability.findMany({
      where: { driverId: driver.id },
      orderBy: { dayOfWeek: 'asc' },
    });

    // If no slots exist, return defaults (Mon-Fri 08-18)
    if (slots.length === 0) {
      const defaults = Array.from({ length: 7 }, (_, i) => ({
        dayOfWeek: i,
        startTime: '08:00',
        endTime: '18:00',
        isActive: i >= 1 && i <= 5, // Mon-Fri active
      }));
      return defaults;
    }

    return slots;
  }

  async setAvailability(
    userId: string,
    slots: {
      dayOfWeek: number;
      startTime: string;
      endTime: string;
      isActive: boolean;
    }[],
  ) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    // Upsert all 7 days
    const results = await Promise.all(
      slots.map((slot) =>
        this.prisma.driverAvailability.upsert({
          where: {
            driverId_dayOfWeek: {
              driverId: driver.id,
              dayOfWeek: slot.dayOfWeek,
            },
          },
          update: {
            startTime: slot.startTime,
            endTime: slot.endTime,
            isActive: slot.isActive,
          },
          create: {
            driverId: driver.id,
            dayOfWeek: slot.dayOfWeek,
            startTime: slot.startTime,
            endTime: slot.endTime,
            isActive: slot.isActive,
          },
        }),
      ),
    );

    return results;
  }

  async toggleDayAvailability(
    userId: string,
    dayOfWeek: number,
    isActive: boolean,
    startTime?: string,
    endTime?: string,
  ) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    return this.prisma.driverAvailability.upsert({
      where: { driverId_dayOfWeek: { driverId: driver.id, dayOfWeek } },
      update: {
        isActive,
        ...(startTime && { startTime }),
        ...(endTime && { endTime }),
      },
      create: {
        driverId: driver.id,
        dayOfWeek,
        startTime: startTime || '08:00',
        endTime: endTime || '18:00',
        isActive,
      },
    });
  }

  // ── Undo booking status (one step back) ─────────────────────
  // X1 fix: explicit server-side undo map — client cannot supply arbitrary statuses.
  // DELIVERED cannot be undone. Every undo is audited.
  async undoBookingStatus(bookingId: string, userId: string) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    const booking = await this.prisma.booking.findFirst({
      where: { id: bookingId, driverId: driver.id },
    });
    if (!booking) throw new NotFoundException('Booking not found');

    const previousStatus = DRIVER_UNDO_MAP[booking.status];
    if (!previousStatus) {
      throw new ConflictException(
        `Cannot undo from status ${booking.status}. Undo is only allowed for: ${Object.keys(DRIVER_UNDO_MAP).join(', ')}.`,
      );
    }

    const updated = await this.prisma.booking.update({
      where: { id: bookingId },
      data: { status: previousStatus },
    });

    await this.audit.logChange(
      bookingId,
      userId,
      'STATUS_CHANGED',
      { status: booking.status },
      { status: previousStatus, source: 'driver_undo' },
    );

    this.tracking.broadcastToManagers('dashboard-updated');
    this.tracking.broadcastToDriver(driver.id, 'assignments-updated');

    return updated;
  }

  // ── Flag an item ──────────────────────────────────────────
  async flagItem(
    bookingId: string,
    itemId: string,
    note: string,
    userId: string,
  ) {
    const driver = await this.prisma.driver.findUnique({ where: { userId } });
    if (!driver) throw new NotFoundException('Driver profile not found');

    const booking = await this.prisma.booking.findFirst({
      where: { id: bookingId, driverId: driver.id },
    });
    if (!booking) throw new NotFoundException('Booking not found');

    // R1-IDOR: Verify the item actually belongs to this booking before updating
    const item = await this.prisma.bookingItem.findFirst({
      where: { id: itemId, bookingId },
    });
    if (!item) throw new NotFoundException('Item not found on this booking');

    return this.prisma.bookingItem.update({
      where: { id: itemId },
      data: { driverFlagNote: note, flagReason: note, driverFlagged: true },
    });
  }
}

import {
  IsNumber,
  IsEnum,
  IsString,
  IsOptional,
  IsBoolean,
  ValidateNested,
  IsArray,
} from 'class-validator';
import { Type } from 'class-transformer';
import { BookingStatus } from '@prisma/client';

export class UpdateLocationDto {
  @IsNumber() lat: number;
  @IsNumber() lng: number;
}

export class UpdateBookingStatusDto {
  @IsEnum(['ARRIVED', 'PACKED', 'LOADED', 'IN_TRANSIT', 'UNLOADING', 'DELIVERED', 'UNREACHABLE'])
  status: BookingStatus;
  @IsOptional() @IsString() truckPhoto?: string;
  @IsOptional() @IsString() deliveryPhoto?: string;
  @IsOptional() @IsString() customerSignature?: string;
  @IsOptional() @IsNumber() extraTimeHours?: number;
  @IsOptional() @IsString() extraTimePayment?: string;
  @IsOptional() @IsNumber() extraPackingTimeHours?: number;
  @IsOptional() @IsNumber() extraPackingMaterialsCost?: number;
}

export class ApplyAsDriverDto {
  @IsOptional() @IsString() licensingAuthority?: string;
  @IsOptional() @IsBoolean() hasVan?: boolean;
}

export class UploadDocumentDto {
  @IsString() docType: string;
  @IsString() label: string;
  @IsString() fileName: string;
  @IsOptional() @IsString() fileUrl?: string;
}

export class AvailabilitySlotDto {
  @IsNumber() dayOfWeek: number; // 0-6
  @IsString() startTime: string; // "08:00"
  @IsString() endTime: string;   // "18:00"
  @IsBoolean() isActive: boolean;
}

export class SetAvailabilityDto {
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => AvailabilitySlotDto)
  slots: AvailabilitySlotDto[];
}

export class ToggleDayDto {
  @IsBoolean() isActive: boolean;
  @IsOptional() @IsString() startTime?: string;
  @IsOptional() @IsString() endTime?: string;
}

import { NestFactory } from '@nestjs/core';
import { ValidationPipe } from '@nestjs/common';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import { AppModule } from './app.module';
import { NestExpressApplication } from '@nestjs/platform-express';
import { join } from 'path';
import helmet from 'helmet';

async function bootstrap() {
  console.log('🚀 Starting API bootstrap process...');
  console.log(
    '🔍 Checking DATABASE_URL: ',
    process.env.DATABASE_URL ? 'SET' : 'MISSING',
  );
  console.log('⚙️  Creating Nest application...');
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true, // needed for Stripe webhook signature
  });
  app.use(
    helmet({
      crossOriginResourcePolicy: false,
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          scriptSrc: [
            "'self'",
            "'unsafe-inline'",
            "'unsafe-eval'",
            'https://js.stripe.com',
            'https://maps.googleapis.com',
          ],
          styleSrc: [
            "'self'",
            "'unsafe-inline'",
            'https://fonts.googleapis.com',
          ],
          fontSrc: ["'self'", 'https://fonts.gstatic.com', 'data:'],
          imgSrc: ["'self'", 'data:', 'https:', 'blob:'],
          connectSrc: [
            "'self'",
            'https://api.stripe.com',
            'https://r.stripe.com',
            'https://maps.googleapis.com',
            'https://*.stripe.com',
          ],
          frameSrc: [
            "'self'",
            'https://js.stripe.com',
            'https://hooks.stripe.com',
          ],
          objectSrc: ["'none'"],
          baseUri: ["'self'"],
        },
      },
    }),
  );
  console.log('✅ Nest application created successfully.');

  // Serve uploaded files statically on both /uploads/ and /api/uploads/
  app.useStaticAssets(join(process.cwd(), 'uploads'), {
    prefix: '/uploads/',
  });
  app.useStaticAssets(join(process.cwd(), 'uploads'), {
    prefix: '/api/uploads/',
  });

  // Global prefix
  app.setGlobalPrefix('api');

  // Validation pipe — strips unknown fields, validates all DTOs
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  // CORS
  const allowedOrigins = [
    'https://www.nglob.com',
    'https://nglob.com',
    'https://app.nglob.com',
    'https://manager.nglob.com',
    'https://driver.nglob.com',
    'https://admin.nglob.com',
    'https://ngob.vercel.app',
    'http://localhost:3000',
    'http://localhost:8081',
    'http://nglob.localhost:3000',
    'http://manager.nglob.localhost:3000',
    'http://driver.nglob.localhost:3000',
    'http://admin.nglob.localhost:3000',
    'http://app.nglob.localhost:3000',

  ];
  if (
    process.env.FRONTEND_URL &&
    !allowedOrigins.includes(process.env.FRONTEND_URL)
  ) {
    allowedOrigins.push(process.env.FRONTEND_URL);
  }

  app.enableCors({
    origin: allowedOrigins,
    methods: 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS',
    credentials: true,
  });

  // Swagger docs at /api/docs
  const config = new DocumentBuilder()
    .setTitle('Removals API')
    .setDescription('UK removals & storage booking platform API')
    .setVersion('1.0')
    .addBearerAuth()
    .build();
  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api/docs', app, document);

  await app.listen(process.env.PORT || 3001);
  console.log(`🚚 Removals API running on port ${process.env.PORT || 3001}`);
  console.log(
    `📚 Swagger docs: http://localhost:${process.env.PORT || 3001}/api/docs`,
  );
}
bootstrap();
// Trigger restart

