import {
  Injectable, ConflictException, NotFoundException, BadRequestException, Logger,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { TrackingGateway } from '../tracking/tracking.gateway';
import { AuditService } from '../audit/audit.service';
import { PricingService } from '../pricing/pricing.service';
import { PaymentsService } from '../payments/payments.service';
import { NotificationService } from '../notifications/notification.service';
import { BookingStatus, DriverStatus, NotificationType, PaymentMethod } from '@prisma/client';
import { ACTIVE_BOOKING_STATUSES, m3ToSqft } from '../common/constants';
import { assertValidTransition } from '../bookings/booking-state';
import { ManagerBookingsQueryDto, ApplyAsManagerDto } from './dto/manager.dto';
import { MANAGER_BOOKING_SELECT } from './manager.select';

export { ManagerBookingsQueryDto, ApplyAsManagerDto };

@Injectable()
export class ManagerService {
  private readonly logger = new Logger(ManagerService.name);

  constructor(
    private prisma: PrismaService,
    private tracking: TrackingGateway,
    private audit: AuditService,
    private pricingService: PricingService,
    private paymentsService: PaymentsService,
    private notificationService: NotificationService,
  ) {}

  // ── Apply as a manager ──────────────────────────────────────
  async applyAsManager(userId: string, dto: ApplyAsManagerDto) {
    const existing = await this.prisma.managerApplication.findUnique({
      where: { userId },
    });
    if (existing) {
      if (existing.status === 'REJECTED') {
        // Allow re-application after rejection
        return this.prisma.managerApplication.update({
          where: { userId },
          data: {
            experience: dto.experience,
            phone: dto.phone,
            status: 'PENDING',
            adminNotes: null,
          },
          include: { user: { select: { name: true, email: true } } },
        });
      }
      throw new ConflictException('You have already applied as a manager');
    }

    return this.prisma.managerApplication.create({
      data: {
        userId,
        experience: dto.experience,
        phone: dto.phone,
        status: 'PENDING',
      },
      include: { user: { select: { name: true, email: true } } },
    });
  }

  // ── Get application status ──────────────────────────────────
  async getApplicationStatus(userId: string) {
    const application = await this.prisma.managerApplication.findUnique({
      where: { userId },
      select: {
        id: true,
        status: true,
        adminNotes: true,
        createdAt: true,
        updatedAt: true,
      },
    });
    return application; // null if hasn't applied
  }

  // ── Get all bookings (global for managers) ─────────────────────────────────
  async getAllBookings(query: ManagerBookingsQueryDto) {
    const where: any = {};

    if (query.status) {
      where.status = query.status;
    } else if (
      query.includeHistorical !== 'true' &&
      query.includeHistorical !== '1'
    ) {
      // By default exclude completed/cancelled bookings for a cleaner dashboard view
      where.status = {
        notIn: [BookingStatus.DELIVERED, BookingStatus.CANCELLED],
      };
    }

    if (query.date) {
      const d = new Date(query.date);
      const next = new Date(d);
      next.setDate(next.getDate() + 1);
      where.pickupDate = { gte: d, lt: next };
    }

    if (query.driverId) where.driverId = query.driverId;

    const [bookings, total] = await Promise.all([
      this.prisma.booking.findMany({
        where,
        select: MANAGER_BOOKING_SELECT,
        orderBy: { pickupDate: 'asc' },
      }),
      this.prisma.booking.count({ where }),
    ]);

    return { bookings, total };
  }

  // ── Shared helpers ──────────────────────────────────────
  private async refundSafely(bookingId: string) {
    try {
      await this.paymentsService.refundBooking(bookingId);
    } catch (e: any) {
      this.logger.error(`Refund failed for ${bookingId}: ${e?.message}`);
    }
  }

  private async notifyCustomer(userId: string, title: string, message: string, bookingId: string) {
    await this.notificationService
      .createNotification(userId, NotificationType.STATUS_CHANGE, title, message, { bookingId })
      .catch(() => undefined);
  }

  // ── Confirm Booking (Manager UI) ─────────────────────────
  async confirmBooking(bookingId: string, actorId: string) {
    const before = await this.prisma.booking.findUnique({
      where: { id: bookingId },
      include: { invoice: true },
    });
    if (!before) throw new NotFoundException('Booking not found');
    assertValidTransition(before.status, BookingStatus.CONFIRMED);

    // Never approve an unpaid cart.
    // Sync any PENDING payments against Stripe live first — this handles the
    // case where the webhook was missed (e.g. placeholder webhook secret in dev
    // or a genuine delivery failure in production).
    await this.paymentsService.syncPendingPayments(bookingId);

    const paid = await this.prisma.payment.count({ where: { bookingId, status: 'SUCCEEDED' } });
    if (!paid && !before.invoice) throw new ConflictException('Booking has no successful payment or invoice');

    const { count } = await this.prisma.booking.updateMany({
      where: { id: bookingId, status: before.status },
      data: { status: BookingStatus.CONFIRMED },
    });
    if (!count) throw new ConflictException('Booking changed, refresh and retry');

    await this.audit.logChange(bookingId, actorId, 'STATUS_CHANGED', { status: before.status }, { status: BookingStatus.CONFIRMED });
    this.tracking.broadcastToManagers('dashboard-updated');
    return this.prisma.booking.findUniqueOrThrow({ where: { id: bookingId } });
  }

  // ── Cancel Booking (Manager UI) ──────────────────────────
  async cancelBooking(bookingId: string, actorId: string) {
    const target = await this.prisma.booking.findUnique({ where: { id: bookingId } });
    if (!target) throw new NotFoundException('Booking not found');
    assertValidTransition(target.status, BookingStatus.CANCELLED);

    const { count } = await this.prisma.booking.updateMany({
      where: { id: bookingId, status: target.status },
      data: { status: BookingStatus.CANCELLED },
    });
    if (!count) throw new ConflictException('Booking changed, refresh and retry');

    await this.refundSafely(bookingId);
    await this.audit.logChange(bookingId, actorId, 'ORDER_CANCELLED', { status: target.status }, { status: BookingStatus.CANCELLED, reason: 'Manager cancelled' });
    await this.notifyCustomer(target.userId, 'Booking cancelled', `Your booking ${target.bookingRef} was cancelled. Any payment will be refunded.`, bookingId);

    this.tracking.broadcastToManagers('dashboard-updated');
    if (target.driverId) this.tracking.broadcastToDriver(target.driverId, 'assignments-updated');
    return this.prisma.booking.findUniqueOrThrow({ where: { id: bookingId } });
  }

  // ── Decline Booking (Manager UI) ─────────────────────────
  async declineBooking(bookingId: string, actorId: string, reason?: string) {
    const target = await this.prisma.booking.findUnique({ where: { id: bookingId } });
    if (!target) throw new NotFoundException('Booking not found');
    if (target.status !== BookingStatus.PENDING && target.status !== BookingStatus.CONFIRMED) {
      throw new ConflictException(`Cannot decline a booking in status ${target.status}. Use cancel for active bookings.`);
    }

    const { count } = await this.prisma.booking.updateMany({
      where: { id: bookingId, status: target.status },
      data: { status: BookingStatus.CANCELLED },
    });
    if (!count) throw new ConflictException('Booking changed, refresh and retry');

    if (target.status === BookingStatus.CONFIRMED) await this.refundSafely(bookingId);
    await this.audit.logChange(bookingId, actorId, 'ORDER_DECLINED', { status: target.status }, { status: BookingStatus.CANCELLED, reason: reason || 'Manager declined' });
    await this.notifyCustomer(target.userId, 'Booking declined', `We could not accept booking ${target.bookingRef}.${reason ? ` Reason: ${reason}` : ''}`, bookingId);

    this.tracking.broadcastToManagers('dashboard-updated');
    return this.prisma.booking.findUniqueOrThrow({ where: { id: bookingId } });
  }

  async updateStorageDetails(
    bookingId: string,
    destinationAddress: string,
    volumeM3: number,
    actorId?: string,
  ) {
    if (!Number.isFinite(volumeM3) || volumeM3 <= 0) {
      throw new BadRequestException('Volume must be a positive number');
    }
    if (!destinationAddress?.trim()) {
      throw new BadRequestException('Destination address is required');
    }

    const target = await this.prisma.booking.findUnique({
      where: { id: bookingId },
      include: { storage: true },
    });
    if (!target) throw new NotFoundException('Booking not found');
    if (!target.withStorage) throw new ConflictException('Booking does not have storage enabled.');

    const settings = await this.pricingService.getSettings();
    const sqft = m3ToSqft(volumeM3);
    const weeklyPrice = Math.round(sqft * settings.storageRatePerSqftPerWeek * 100) / 100;
    const weeks = target.storageWeeks ?? 1;
    const newStorageCost = Math.round(weeklyPrice * weeks * 100) / 100;
    const delta = newStorageCost - (target.storageCost ?? 0);

    const updated = await this.prisma.$transaction(async (tx) => {
      if (target.storage) {
        await tx.storage.update({ where: { id: target.storage.id }, data: { volumeM3, weeklyPrice } });
      }
      return tx.booking.update({
        where: { id: bookingId },
        data: {
          destinationAddress,
          storageCost: newStorageCost,
          totalPrice: { increment: delta },
        },
        include: { storage: true },
      });
    });

    if (actorId) {
      await this.audit.logChange(
        bookingId, actorId, 'STORAGE_UPDATED',
        { destinationAddress: target.destinationAddress, storageCost: target.storageCost },
        { destinationAddress, volumeM3, storageCost: newStorageCost },
      );
    }
    this.tracking.broadcastToManagers('dashboard-updated');
    if (updated.driverId) this.tracking.broadcastToDriver(updated.driverId, 'assignments-updated');
    return updated;
  }

  async assignDriver(
    bookingId: string,
    driverId: string,
    crewIds?: string[],
    actorId?: string,
  ) {
    const targetBooking = await this.prisma.booking.findUnique({
      where: { id: bookingId },
    });
    if (!targetBooking) throw new NotFoundException('Booking not found');

    const allDriverIds = [driverId, ...(crewIds || [])];

    const targetDateStart = new Date(targetBooking.pickupDate);
    targetDateStart.setHours(0, 0, 0, 0);
    const targetDateEnd = new Date(targetDateStart);
    targetDateEnd.setDate(targetDateEnd.getDate() + 1);

    const activeBookings = await this.prisma.booking.findMany({
      where: {
        id: { not: bookingId }, // R1-8: Exclude target booking to avoid self-overlap
        status: { in: ACTIVE_BOOKING_STATUSES },
        pickupDate: { gte: targetDateStart, lt: targetDateEnd },
        OR: [
          { driverId: { in: allDriverIds } },
          { crew: { some: { driverId: { in: allDriverIds } } } },
        ],
      },
    });

    // Check availability (F14.2)
    const parseSlotStart = (slot?: string) => {
      if (!slot) return 8;
      const parts = slot.replace('SLOT_', '').split('_').map(Number);
      return parts[0] || 8;
    };

    const targetStartHour = parseSlotStart(targetBooking.pickupTimeSlot);
    const targetStartMin = targetStartHour * 60;
    // R1-8: estimatedDuration is in minutes. Don't divide by 60.
    const targetEndMin = targetStartMin + (targetBooking.estimatedDuration || 0) + 60; // 1 hour travel buffer

    for (const b of activeBookings) {
      if (targetBooking.type === 'FULL_HOUSE' || b.type === 'FULL_HOUSE') {
        throw new ConflictException('Driver is already assigned to a full house removal today (or this is a full house removal and driver has other jobs).');
      }

      const bStartHour = parseSlotStart(b.pickupTimeSlot);
      const bStartMin = bStartHour * 60;
      const bEndMin = bStartMin + (b.estimatedDuration || 0) + 60;

      // M6 fix: Allow FEW_ITEMS to overlap with each other for batching
      if (targetBooking.type === 'FEW_ITEMS' && b.type === 'FEW_ITEMS') {
        continue;
      }

      // Overlap check
      if (Math.max(targetStartMin, bStartMin) < Math.min(targetEndMin, bEndMin)) {
        throw new ConflictException(`Driver has an overlapping job (${b.bookingRef}) at ${bStartHour}:00.`);
      }
    }



    // R1-4: Prevent assigning driver from modifying CANCELLED/DELIVERED bookings
    // or bypassing payment on PENDING ones.
    const allowedStatusesForAssignment: BookingStatus[] = [
      BookingStatus.CONFIRMED,
      BookingStatus.SCHEDULED,
      BookingStatus.UNREACHABLE,
    ];
    if (!allowedStatusesForAssignment.includes(targetBooking.status)) {
      throw new ConflictException(`Cannot assign driver to booking in ${targetBooking.status} status. It must be paid and confirmed.`);
    }

    const data: any = { driverId, status: BookingStatus.SCHEDULED };

    // X2 fix: always deleteMany to clear out old crew. If crewIds is present, create new ones.
    data.crew = { deleteMany: {} };
    if (crewIds && crewIds.length > 0) {
      data.crew.create = crewIds.map((id) => ({ driverId: id }));
    }

    // R1-8: Driver availability/status check
    const drivers = await this.prisma.driver.findMany({
      where: { id: { in: allDriverIds } }
    });
    for (const d of drivers) {
      if (d.status !== 'APPROVED') {
        throw new ConflictException(`Driver ${d.id} is not approved for jobs.`);
      }
    }

    const updated = await this.prisma.booking.update({
      where: { id: bookingId },
      data,
      include: {
        // R1-1: Use select to prevent password hash leak
        driver: { include: { user: { select: { name: true, phone: true } } } },
        crew: { include: { driver: { include: { user: { select: { name: true, phone: true } } } } } },
      },
    });
    if (actorId) {
      await this.audit.logChange(
        bookingId,
        actorId,
        'DRIVER_ASSIGNED',
        { driverId: targetBooking.driverId },
        { driverId, status: updated.status, crewIds },
      );
    }
    this.tracking.broadcastToManagers('dashboard-updated');
    this.tracking.broadcastToDriver(driverId, 'assignments-updated');
    if (crewIds) {
      for (const cid of crewIds) {
        this.tracking.broadcastToDriver(cid, 'assignments-updated');
      }
    }
    // R1-8: Notify old driver if reassigned
    if (targetBooking.driverId && targetBooking.driverId !== driverId) {
      this.tracking.broadcastToDriver(targetBooking.driverId, 'assignments-updated');
    }
    return updated;
  }

  // ── Bulk assign drivers (atomic transaction) ────────────────────────────────
  async bulkAssignDrivers(
    assignments: Array<{
      bookingId: string;
      driverId: string;
      crewIds?: string[];
    }>,
    actorId: string,
  ): Promise<{
    results: Array<{ bookingId: string; success: boolean; error?: string }>;
  }> {
    const results: Array<{
      bookingId: string;
      success: boolean;
      error?: string;
    }> = [];

    // F14.1: Remove overarching transaction to allow partial success
    for (const assignment of assignments) {
      try {
        await this.assignDriver(assignment.bookingId, assignment.driverId, assignment.crewIds, actorId);
        results.push({ bookingId: assignment.bookingId, success: true });
      } catch (err: any) {
        results.push({ bookingId: assignment.bookingId, success: false, error: err.message || 'Failed' });
      }
    }

    return { results };
  }

  // ── Get drivers (global for managers) ──────────────────
  async getDrivers() {
    const bookingWhere = {
      status: { in: ACTIVE_BOOKING_STATUSES },
      pickupDate: { gte: new Date(new Date().setUTCHours(0, 0, 0, 0)) },
    };

    const drivers = await this.prisma.driver.findMany({
      include: {
        user: { select: { name: true, phone: true, email: true } },
        bookings: {
          where: bookingWhere,
          select: { id: true, pickupDate: true, status: true, type: true },
        },
        // The relation is named crewBookings in the schema (was `crew` → Prisma error)
        crewBookings: {
          where: { booking: bookingWhere },
          select: {
            booking: { select: { id: true, pickupDate: true, status: true, type: true } },
          },
        },
        availability: { orderBy: { dayOfWeek: 'asc' } },
        documents: { select: { id: true, docType: true, status: true } }, // no fileUrl in list
      },
    });

    // Flatten crew jobs into `bookings` so the hub's conflict check sees them
    return drivers.map(({ crewBookings, ...d }) => ({
      ...d,
      bookings: [...d.bookings, ...crewBookings.map((c) => c.booking)],
    }));
  }

  // ── Dashboard stats (global for managers) ──────────────
  // N31: getDashboardStats — pendingPayment = unpaid carts only
  async getDashboardStats() {
    const todayStart = new Date();
    todayStart.setUTCHours(0, 0, 0, 0);
    const todayEnd = new Date();
    todayEnd.setUTCHours(23, 59, 59, 999);

    return Promise.all([
      this.prisma.booking.count({ where: { status: BookingStatus.SCHEDULED, pickupDate: { gte: todayStart, lte: todayEnd } } }),
      // pendingPayment = unpaid carts
      this.prisma.booking.count({ where: { status: BookingStatus.PENDING } }),
      this.prisma.storage.count({ where: { status: 'ACTIVE' } }),
      this.prisma.booking.aggregate({ _sum: { totalPrice: true }, where: { status: BookingStatus.DELIVERED } }),
      this.prisma.driver.count({ where: { status: DriverStatus.PENDING } }),
      this.prisma.booking.count({ where: { status: BookingStatus.CONFIRMED } }),
    ]).then(([scheduled, pending, activeStorage, revenue, pendingDrivers, confirmed]) => ({
      scheduledToday: scheduled,
      pendingPayment: pending,
      activeStorage,
      totalRevenue: revenue._sum.totalPrice ?? 0,
      pendingDrivers,
      confirmedOrders: confirmed,
    }));
  }

  // N20: updateDriverStatus with doc check and role alignment
  async updateDriverStatus(driverId: string, status: DriverStatus) {
    if (status === DriverStatus.APPROVED) {
      const docs = await this.prisma.driverDocument.findMany({ where: { driverId } });
      if (docs.length === 0 || docs.some((d) => d.status !== 'APPROVED')) {
        throw new ConflictException('Every required document must be APPROVED before approving the driver');
      }
    }

    const driver = await this.prisma.driver.update({
      where: { id: driverId },
      data: { status },
      include: { user: { select: { id: true, name: true, email: true, role: true } } },
    });

    if (status === DriverStatus.REJECTED && driver.user.role === 'DRIVER') {
      await this.prisma.user.update({ where: { id: driver.user.id }, data: { role: 'CUSTOMER' } });
    } else if (status === DriverStatus.APPROVED && driver.user.role === 'CUSTOMER') {
      // never overwrite MANAGER / ADMIN / BUSINESS
      await this.prisma.user.update({ where: { id: driver.user.id }, data: { role: 'DRIVER' } });
    }
    return driver;
  }

  // ── Get driver documents (for review) ──────────────────────
  async getDriverDocuments(driverId: string) {
    const driver = await this.prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        user: { select: { name: true, email: true, phone: true } },
        documents: { orderBy: { createdAt: 'asc' } },
      },
    });
    if (!driver) throw new NotFoundException('Driver not found');
    return driver;
  }

  // ── Get all drivers with their documents ───────────────────
  async getDriversWithDocuments() {
    return this.prisma.driver.findMany({
      include: {
        user: { select: { name: true, email: true, phone: true } },
        documents: { orderBy: { createdAt: 'asc' } },
      },
      orderBy: { createdAt: 'desc' },
    });
  }

  // ── Review a single document ───────────────────────────────
  async reviewDocument(
    documentId: string,
    status: 'APPROVED' | 'REJECTED',
    reviewNote?: string,
  ) {
    const doc = await this.prisma.driverDocument.findUnique({
      where: { id: documentId },
    });
    if (!doc) throw new NotFoundException('Document not found');

    return this.prisma.driverDocument.update({
      where: { id: documentId },
      data: {
        status,
        reviewNote: reviewNote || null,
        reviewedAt: new Date(),
      },
    });
  }

  // ── Active rides (live view for managers) ──────────────────
  async getActiveRides() {
    const rides = await this.prisma.booking.findMany({
      where: {
        status: { in: ACTIVE_BOOKING_STATUSES },
      },
      include: {
        user: { select: { name: true, phone: true, email: true } },
        driver: {
          include: {
            user: { select: { name: true, phone: true, email: true } },
          },
        },
        items: true,
        storage: { include: { items: true } },
        packingMaterials: true,
      },
      orderBy: { pickupDate: 'asc' },
    });

    return rides.filter((r: any) => r.status !== BookingStatus.CANCELLED);
  }

  // ── Ride detail (with history) ─────────────────────────────
  async getRideDetail(bookingId: string) {
    const booking = await this.prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        user: { select: { name: true, phone: true, email: true } },
        driver: {
          include: {
            user: { select: { name: true, phone: true, email: true } },
          },
        },
        items: true,
        storage: { include: { items: true } },
        packingMaterials: true,
        auditLogs: { orderBy: { createdAt: 'desc' }, take: 20 },
        payments: true,
      },
    });
    if (!booking) throw new NotFoundException('Booking not found');
    return booking;
  }

  // ── Completed rides (recent history) ───────────────────────
  async getCompletedRides(limit = 20) {
    return this.prisma.booking.findMany({
      where: {
        status: { in: [BookingStatus.DELIVERED, BookingStatus.UNREACHABLE] },
        driverId: { not: null },
      },
      include: {
        user: { select: { name: true, phone: true, email: true } },
        driver: {
          include: {
            user: { select: { name: true, phone: true, email: true } },
          },
        },
        items: true,
        storage: { include: { items: true } },
        packingMaterials: true,
      },
      orderBy: { updatedAt: 'desc' },
      take: limit,
    });
  }

  // N23: Re-queue an UNREACHABLE booking back to CONFIRMED with no driver
  async requeueUnreachable(bookingId: string, actorId: string) {
    const b = await this.prisma.booking.findUnique({ where: { id: bookingId } });
    if (!b) throw new NotFoundException('Booking not found');
    if (b.status !== BookingStatus.UNREACHABLE) throw new ConflictException('Only UNREACHABLE bookings can be re-queued');
    assertValidTransition(b.status, BookingStatus.CONFIRMED);

    const updated = await this.prisma.booking.update({
      where: { id: bookingId },
      data: { status: BookingStatus.CONFIRMED, driverId: null, crew: { deleteMany: {} } },
    });
    await this.audit.logChange(bookingId, actorId, 'REQUEUED', { status: b.status, driverId: b.driverId }, { status: BookingStatus.CONFIRMED });
    this.tracking.broadcastToManagers('dashboard-updated');
    if (b.driverId) this.tracking.broadcastToDriver(b.driverId, 'assignments-updated');
    return updated;
  }
}

import { PaymentStatus } from '@prisma/client';

/** Computed payment state derived from Payment records. */
export type PaymentState =
  | 'UNPAID'
  | 'PENDING'
  | 'PARTIALLY_PAID'
  | 'PAID'
  | 'FAILED'
  | 'REFUNDED';

/**
 * Compute the authoritative payment state for a booking.
 *
 * Rules:
 * - UNPAID          — no payment records at all
 * - PENDING         — at least one PENDING record, no SUCCEEDED
 * - PAID            — amountPaid >= totalPrice
 * - PARTIALLY_PAID  — amountPaid > 0 but < totalPrice
 * - FAILED          — most recent payment FAILED, nothing SUCCEEDED
 * - REFUNDED        — has a REFUNDED record, nothing SUCCEEDED
 */
export function computePaymentState(
  payments: Array<{ status: PaymentStatus; amount: number }>,
  totalPrice: number,
): { paymentState: PaymentState; amountPaid: number; amountDue: number } {
  if (!payments || payments.length === 0) {
    return {
      paymentState: 'UNPAID',
      amountPaid: 0,
      amountDue: totalPrice,
    };
  }

  const amountPaid = payments
    .filter((p) => p.status === PaymentStatus.SUCCEEDED && !(p as any).isExtraTime)
    .reduce((sum, p) => sum + p.amount, 0);

  const amountDue = Math.max(
    Math.round((totalPrice - amountPaid) * 100) / 100,
    0,
  );

  const hasRefunded = payments.some((p) => p.status === PaymentStatus.REFUNDED);
  const hasPending = payments.some((p) => p.status === PaymentStatus.PENDING);
  const hasFailed = payments.some((p) => p.status === PaymentStatus.FAILED);

  let paymentState: PaymentState;
  if (hasRefunded && amountPaid === 0) {
    paymentState = 'REFUNDED';
  } else if (amountPaid >= totalPrice) {
    paymentState = 'PAID';
  } else if (amountPaid > 0) {
    paymentState = 'PARTIALLY_PAID';
  } else if (hasPending) {
    paymentState = 'PENDING';
  } else if (hasFailed) {
    paymentState = 'FAILED';
  } else {
    paymentState = 'UNPAID';
  }

  return { paymentState, amountPaid, amountDue };
}

import {
  Injectable,
  BadRequestException,
  NotFoundException,
  ConflictException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { BookingsService } from '../bookings/bookings.service';
import { ConfigService } from '@nestjs/config';
import Stripe = require('stripe');
import { Stripe as StripeTypes } from 'stripe/cjs/stripe.core.js';
import { PaymentStatus } from '@prisma/client';
import { IsOptional, IsString, IsBoolean } from 'class-validator';
import {
  computePaymentState,
  PaymentState,
} from './payment-state.util';

export { PaymentState } from './payment-state.util';

export class CreatePaymentIntentDto {
  @IsOptional() @IsString() bookingId?: string;
  @IsOptional() @IsString() storageDeliveryId?: string;
  @IsOptional() @IsBoolean() isDeposit?: boolean;
  @IsOptional() @IsBoolean() isExtraTime?: boolean;
}



@Injectable()
export class PaymentsService {
  private stripe: StripeTypes;

  constructor(
    private prisma: PrismaService,
    private bookingsService: BookingsService,
    private config: ConfigService,
  ) {
    this.stripe = new Stripe(this.config.get('STRIPE_SECRET_KEY') || '', {
      apiVersion: '2024-06-20' as any,
    });
  }

  // ── Create PaymentIntent (idempotent) ─────────────────────────────────────
  async createIntent(dto: CreatePaymentIntentDto, userId: string) {
    let amountPence: number;
    let metadata: Record<string, string> = { userId };

    if (dto.bookingId) {
      const booking = await this.prisma.booking.findUnique({
        where: { id: dto.bookingId },
        include: {
          payments: { orderBy: { createdAt: 'desc' } },
        },
      });
      if (!booking || booking.userId !== userId) throw new NotFoundException();

      // ── Idempotency: reject if already fully paid ──────────────────────────
      const { paymentState } = computePaymentState(
        booking.payments,
        booking.totalPrice,
      );
      if (paymentState === 'PAID') {
        throw new ConflictException('Booking is already fully paid');
      }

      // ── Idempotency: reuse existing PENDING PaymentIntent ──────────────────
      const existingPending = booking.payments.find(
        (p) =>
          p.status === PaymentStatus.PENDING &&
          p.isDeposit === (dto.isDeposit ?? false),
      );
      if (existingPending) {
        // Retrieve the live PI from Stripe to get a fresh clientSecret
        const existingIntent = await this.stripe.paymentIntents.retrieve(
          existingPending.stripePaymentIntentId,
        );
        // Only reuse if still in a reusable state
        if (
          existingIntent.status === 'requires_payment_method' ||
          existingIntent.status === 'requires_confirmation' ||
          existingIntent.status === 'requires_action'
        ) {
          return { clientSecret: existingIntent.client_secret };
        }
        // Otherwise fall through to create a new one (e.g. PI expired/cancelled)
      }

      const amount = dto.isExtraTime
        ? (booking.extraTimeCost ?? 0)
        : (dto.isDeposit ? (booking.depositAmount ?? booking.totalPrice) : booking.totalPrice);

      amountPence = Math.round(amount * 100);
      metadata = {
        ...metadata,
        bookingId: dto.bookingId,
        isDeposit: dto.isDeposit ? 'true' : 'false',
        isExtraTime: dto.isExtraTime ? 'true' : 'false',
      };
    } else if (dto.storageDeliveryId) {
      const delivery = await this.prisma.storageDelivery.findUnique({
        where: { id: dto.storageDeliveryId },
        include: { storage: true },
      });
      if (!delivery || delivery.storage.userId !== userId) {
        throw new NotFoundException();
      }
      if (delivery.cost === 0) {
        // Free delivery — no payment needed
        return { free: true, clientSecret: null };
      }
      amountPence = Math.round(delivery.cost * 100);
      metadata = { ...metadata, storageDeliveryId: dto.storageDeliveryId };
    } else {
      throw new BadRequestException(
        'Must provide bookingId or storageDeliveryId',
      );
    }

    const intent = await this.stripe.paymentIntents.create({
      amount: amountPence,
      currency: 'gbp',
      metadata,
      automatic_payment_methods: { enabled: true },
    });

    // Record payment intent in DB
    await this.prisma.payment.create({
      data: {
        stripePaymentIntentId: intent.id,
        amount: amountPence / 100,
        status: PaymentStatus.PENDING,
        bookingId: dto.bookingId,
        storageDeliveryId: dto.storageDeliveryId,
        isDeposit: dto.isDeposit ?? false,
        isExtraTime: dto.isExtraTime ?? false,
      },
    });

    return { clientSecret: intent.client_secret };
  }

  // ── Get authoritative payment status for a booking ────────────────────────
  async getBookingPaymentStatus(bookingId: string, userId: string) {
    const booking = await this.prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        payments: { orderBy: { createdAt: 'asc' } },
      },
    });
    if (!booking) throw new NotFoundException('Booking not found');
    if (booking.userId !== userId) throw new NotFoundException('Booking not found');

    const { paymentState, amountPaid, amountDue } = computePaymentState(
      booking.payments,
      booking.totalPrice,
    );

    return {
      bookingId,
      totalPrice: booking.totalPrice,
      amountPaid,
      amountDue,
      paymentState,
      payments: booking.payments.map((p) => ({
        id: p.id,
        amount: p.amount,
        status: p.status,
        isDeposit: p.isDeposit,
        isExtraTime: (p as any).isExtraTime,
        createdAt: p.createdAt,
        updatedAt: p.updatedAt,
      })),
    };
  }

  // ── Refund Payment ────────────────────────────────────────────────────────
  async refundBooking(bookingId: string) {
    const payments = await this.prisma.payment.findMany({
      where: { bookingId, status: PaymentStatus.SUCCEEDED },
    });

    for (const payment of payments) {
      try {
        await this.stripe.refunds.create({
          payment_intent: payment.stripePaymentIntentId,
        });
        await this.prisma.payment.update({
          where: { id: payment.id },
          data: { status: PaymentStatus.REFUNDED },
        });
      } catch (err: any) {
        console.error(`[PaymentsService] Failed to refund payment ${payment.id}:`, err.message);
      }
    }
  }

  // ── Sync PENDING payments against Stripe (webhook reconciliation) ─────────
  /**
   * For every PENDING payment on a booking, retrieve the PaymentIntent from
   * Stripe and, if Stripe already marks it as "succeeded", promote the local
   * record to SUCCEEDED and trigger the same post-payment side-effects that the
   * webhook would have fired.
   *
   * This is the fix for environments where STRIPE_WEBHOOK_SECRET is a
   * placeholder or webhook delivery has genuinely failed.
   */
  async syncPendingPayments(bookingId: string): Promise<void> {
    const pendingPayments = await this.prisma.payment.findMany({
      where: { bookingId, status: PaymentStatus.PENDING },
    });

    for (const payment of pendingPayments) {
      try {
        const intent = await this.stripe.paymentIntents.retrieve(
          payment.stripePaymentIntentId,
        );
        if (intent.status === 'succeeded') {
          await this.handlePaymentSucceeded(intent);
        }
      } catch (err: any) {
        // Non-fatal — log and continue; the guard below will still catch truly unpaid bookings
        console.warn(
          `[PaymentsService] syncPendingPayments: could not retrieve PI ${payment.stripePaymentIntentId}: ${err.message}`,
        );
      }
    }
  }



  // ── Stripe webhook ────────────────────────────────────────────────────────
  async handleWebhook(signature: string, rawBody: Buffer) {
    let event: StripeTypes.Event;
    try {
      event = this.stripe.webhooks.constructEvent(
        rawBody,
        signature,
        this.config.get('STRIPE_WEBHOOK_SECRET') || '',
      );
    } catch {
      throw new BadRequestException('Invalid Stripe webhook signature');
    }

    if (event.type === 'payment_intent.succeeded') {
      const intent = event.data.object as StripeTypes.PaymentIntent;
      await this.handlePaymentSucceeded(intent);
    }

    if (event.type === 'payment_intent.payment_failed') {
      const intent = event.data.object as StripeTypes.PaymentIntent;
      await this.prisma.payment.updateMany({
        where: {
          stripePaymentIntentId: intent.id,
          // Only update if not already in a terminal state
          status: PaymentStatus.PENDING,
        },
        data: { status: PaymentStatus.FAILED },
      });
    }

    return { received: true };
  }

  private async handlePaymentSucceeded(intent: StripeTypes.PaymentIntent) {
    // ── Idempotency guard: skip if already processed ───────────────────────
    const existingPayment = await this.prisma.payment.findUnique({
      where: { stripePaymentIntentId: intent.id },
    });
    if (existingPayment && existingPayment.status === PaymentStatus.SUCCEEDED) {
      // Already processed — return safely without side effects
      console.log(
        `[Webhook] PaymentIntent ${intent.id} already SUCCEEDED — skipping (idempotent)`,
      );
      return;
    }

    // Mark the payment record as succeeded
    await this.prisma.payment.updateMany({
      where: {
        stripePaymentIntentId: intent.id,
        status: PaymentStatus.PENDING,
      },
      data: { status: PaymentStatus.SUCCEEDED },
    });

    const { bookingId, isDeposit, storageDeliveryId, isExtraTime } = intent.metadata || {};

    if (bookingId) {
      if (isExtraTime === 'true') {
        // Extra time payment clears the driver debt
        await this.prisma.booking.update({
          where: { id: bookingId },
          data: { extraTimePayment: 'CARD' },
        });
      } else {
        // Main booking payment
        await this.bookingsService.confirmPayment(bookingId, isDeposit === 'true');
      }
    }

    if (storageDeliveryId) {
      // Mark delivery as scheduled (already was, payment just confirms)
      await this.prisma.storageDelivery.update({
        where: { id: storageDeliveryId },
        data: { status: 'SCHEDULED' },
      });
    }
  }
}

const SIZE: Record<string, number> = { STUDIO: 0.8, ONE: 1, TWO: 1.5, THREE: 2, FOUR_PLUS: 2.6 };
const TIER: Record<string, number> = { ESSENTIALS: 0.6, FULL: 1, PACK_UNPACK: 1.6 };

export const packingPrice = (base: number, homeSize?: string, tier = 'FULL') =>
  Math.round(base * (SIZE[homeSize ?? 'ONE'] ?? 1) * (TIER[tier] ?? 1));

