// ── Geocoding + routing helpers ────────────────────────────────────────────────

interface Coords {
  lat: number;
  lng: number;
}

async function geocodeAddress(address: string): Promise<Coords | null> {
  if (!address?.trim()) return null;
  try {
    const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(address)}&limit=1&countrycodes=gb`;
    const res = await fetch(url, {
      headers: {
        Accept: 'application/json',
        'User-Agent': 'Nglob-Backend/1.0',
      },
      signal: AbortSignal.timeout(8_000),
    });
    if (!res.ok) return null;
    const data = await res.json();
    if (data?.length > 0)
      return { lat: parseFloat(data[0].lat), lng: parseFloat(data[0].lon) };
    return null;
  } catch {
    return null;
  }
}

async function getDrivingDistanceKm(
  start: Coords,
  end: Coords,
): Promise<number | null> {
  try {
    const coords = `${start.lng},${start.lat};${end.lng},${end.lat}`;
    const url = `https://router.project-osrm.org/route/v1/driving/${coords}?overview=false`;
    const res = await fetch(url, { signal: AbortSignal.timeout(8_000) });
    if (!res.ok) return null;
    const data = await res.json();
    if (data?.code === 'Ok' && data.routes?.length > 0) {
      return data.routes[0].distance / 1000; // metres → km
    }
    return null;
  } catch {
    return null;
  }
}

// ── Interfaces ─────────────────────────────────────────────────────────────────

export interface PricingInput {
  homeSize?: HomeSize;
  moversCount: number;
  extras: ExtrasType;
  /** distanceKm is required here; callers can either supply it or call calculateFromAddresses() */
  distanceKm: number;
  items?: Array<{ volumeM3: number; quantity: number }>;
  packingMaterials?: Array<{ type: string; quantity: number }>;
  packingTimeHours?: number;
  withStorage?: boolean;
  storageSqft?: number;
  storageDays?: number;
  storageWeeks?: number;
  /** Exact pickup time string (e.g. "10:30") — triggers exactTimeFee surcharge */
  exactPickupTime?: string;
  /** Number of flights of stairs (£20 per flight) */
  stairsFlights?: number;
  /** Parking distance in metres (£30 surcharge if > 20m) */
  parkingDistance?: number;
  /**
   * Promo / referral code — validated server-side.
   * If valid, the discount is applied BEFORE VAT is extracted.
   */
  promoCode?: string;
  /** User ID — passed down from the controller request when auth is present */
  userId?: string;
  packingTier?: string;
}

export interface PricingAddressInput extends Omit<PricingInput, 'distanceKm'> {
  pickupAddress: string;
  destinationAddress: string;
  pickupLat?: number;
  pickupLng?: number;
  destLat?: number;
  destLng?: number;
}

/**
 * All monetary fields are in PENCE (integer) to avoid floating-point drift.
 * Convert to pounds only at the display layer: value / 100.
 *
 * VAT MODEL: Totals are VAT-INCLUSIVE.
 *   grossComponentsPence = sum of all cost components
 *   discountAmountPence  = server-validated promo discount (applied to gross before VAT extraction)
 *   totalToPayPence      = grossComponentsPence - discountAmountPence
 *   vatAmountPence       = Math.round(totalToPayPence * 20 / 120)  ← extracted, not added
 *   subtotalPence        = totalToPayPence - vatAmountPence
 */
export interface PricingResult {
  distanceKm: number;

  loadingTimeMins: number;
  travelTimeMins: number;
  totalDurationMins: number;
  loadingTimeDisplay: string;
  travelTimeDisplay: string;
  totalDurationDisplay: string;

  // ── Pence amounts ────────────────────────────────────────────
  baseCostPence: number;
  additionalMoverCostPence: number;
  fuelCostPence: number;
  fullPackingCostPence: number;
  packingMaterialsCostPence: number;
  storageCostPence: number;
  exactTimeFeePence: number;
  stairsFeePence: number;
  parkingFeePence: number;
  /** Pence sum of all cost components before discount */
  grossComponentsPence: number;
  /** Pence value of the server-applied promo discount (0 if none) */
  discountAmountPence: number;
  /** = grossComponentsPence − discountAmountPence (VAT-inclusive total) */
  totalToPayPence: number;
  /** = Math.round(totalToPayPence * 20 / 120) — VAT extracted from inclusive total */
  vatAmountPence: number;
  /** = totalToPayPence − vatAmountPence */
  subtotalPence: number;

  // ── Pound convenience (2 dp) — display only ──────────────────
  baseCost: number;
  additionalMoverCost: number;
  fuelCost: number;
  fullPackingCost: number;
  packingMaterialsCost: number;
  storageCost: number;
  exactTimeFee: number;
  stairsFee: number;
  parkingFee: number;
  weeklyStoragePrice: number;
  /** Pound value of the server-applied promo discount */
  discountAmount: number;
  /** VAT-inclusive total after discount */
  totalToPay: number;
  /** VAT extracted from the inclusive total */
  vatAmount: number;
  /** Ex-VAT subtotal = totalToPay − vatAmount */
  subtotal: number;
  /** Applied promo code (undefined if none) */
  appliedPromoCode?: string;
  /** Promo display text (e.g. "20% off") */
  promoDisplayText?: string;
}

// ── Service ────────────────────────────────────────────────────────────────────

@Injectable()
export class PricingService {
  constructor(private readonly prisma: PrismaService) { }

  // ── Settings ─────────────────────────────────────────────────────────────────

  async getSettings() {
    try {
      let settings = await this.prisma.pricingSettings.findUnique({
        where: { id: 'global' },
      });
      if (!settings) {
        settings = await this.prisma.pricingSettings.create({
          data: { id: 'global' },
        });
      }
      return settings;
    } catch (e: any) {
      console.warn(
        'DB connection failed, using mock settings. Error:',
        e?.message || e,
      );
      return {
        baseRatePerHour: 60,
        additionalMoverPerHour: 15,
        fullPackingCost: 230,
        fuelRatePerMile: 1.8,
        storageRatePerSqftPerWeek: 0.8,
        storageDeliveryFee: 24,
        fee1Bed: 30,
        fee2Bed: 60,
        fee3Bed: 100,
        fee4Bed: 150,
        materialMediumBox: 4.0,
        materialLargeBox: 7.0,
        materialBubbleWrap: 7.0,
        materialPaperRoll: 5.0,
        materialTape: 1.0,
        exactTimeFee: 60,
      } as any;
    }
  }

  async updateSettings(data: any) {
    return this.prisma.pricingSettings.upsert({
      where: { id: 'global' },
      update: data,
      create: { id: 'global', ...data },
    });
  }

  // ── AI demand suggestion ──────────────────────────────────────────────────────

  async getAiSuggestion() {
    const oneWeekAgo = new Date();
    oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

    const recentBookingsCount = await this.prisma.booking.count({
      where: { createdAt: { gte: oneWeekAgo } },
    });

    const currentSettings = await this.getSettings();

    let suggestedAction = '';
    let modifier = 1;
    let logic = '';

    if (recentBookingsCount > 20) {
      suggestedAction = 'Increase Prices';
      modifier = 1.15;
      logic = `High Demand Detected (${recentBookingsCount} bookings in 7 days). Raising prices will maximise profit while maintaining full schedule.`;
    } else if (recentBookingsCount < 5) {
      suggestedAction = 'Decrease Prices';
      modifier = 0.9;
      logic = `Low Demand Detected (${recentBookingsCount} bookings in 7 days). Lowering prices will attract more customers and fill idle fleet capacity.`;
    } else {
      suggestedAction = 'Maintain Prices';
      modifier = 1.0;
      logic = `Stable Demand Detected (${recentBookingsCount} bookings in 7 days). Current pricing is optimal for current market conditions.`;
    }

    return {
      action: suggestedAction,
      logic,
      metrics: {
        recentBookings: recentBookingsCount,
        competitorAverage: '£65/hr',
      },
      suggestedSettings: {
        baseRatePerHour: Math.round(currentSettings.baseRatePerHour * modifier),
        additionalMoverPerHour: Math.round(
          currentSettings.additionalMoverPerHour * modifier,
        ),
        fuelRatePerMile:
          Math.round(currentSettings.fuelRatePerMile * modifier * 100) / 100,
        fullPackingCost: Math.round(currentSettings.fullPackingCost * modifier),
        storageRatePerSqftPerWeek:
          Math.round(
            currentSettings.storageRatePerSqftPerWeek * modifier * 100,
          ) / 100,
        storageDeliveryFee: Math.round(
          currentSettings.storageDeliveryFee * modifier,
        ),
      },
    };
  }

  // ── Storage helpers ───────────────────────────────────────────────────────────

  async calculateStoragePrice(sqft: number): Promise<number> {
    const settings = await this.getSettings();
    // Returns weekly price in pounds (2 dp)
    return Math.round(sqft * settings.storageRatePerSqftPerWeek * 100) / 100;
  }

  getRecommendedSqft(homeSize: string): number {
    return PRICING_ADDITIONS.RECOMMENDED_STORAGE_SQFT[homeSize] || 50;
  }

  async calculateStorageBookingTotal(params: {
    movingPriceBase: number;
    sqft: number;
    includeDeliveryToStorage: boolean;
    includeDeliveryFromStorage: boolean;
  }): Promise<{
    weeklyStoragePrice: number;
    deliveryToStorageFee: number;
    deliveryFromStorageFee: number;
    payTodayTotal: number;
    payWeeklyAmount: number;
  }> {
    const settings = await this.getSettings();
    const weeklyStoragePrice = await this.calculateStoragePrice(params.sqft);
    const deliveryToStorageFee = params.includeDeliveryToStorage
      ? settings.storageDeliveryFee
      : 0;
    const deliveryFromStorageFee = params.includeDeliveryFromStorage
      ? settings.storageDeliveryFee
      : 0;

    return {
      weeklyStoragePrice,
      deliveryToStorageFee,
      deliveryFromStorageFee,
      payTodayTotal:
        params.movingPriceBase + weeklyStoragePrice + deliveryToStorageFee,
      payWeeklyAmount: weeklyStoragePrice,
    };
  }

  // ── Address-based calculation (geocodes internally) ───────────────────────────

  /**
   * Geocodes pickup and destination, fetches driving distance via OSRM,
   * then runs the full pricing calculation.
   * Throws BadRequestException if geocoding or routing fails.
   */
  async calculateFromAddresses(
    input: PricingAddressInput,
  ): Promise<PricingResult> {
    let pickupCoords: Coords | null = input.pickupLat && input.pickupLng
      ? { lat: input.pickupLat, lng: input.pickupLng }
      : null;
    let destCoords: Coords | null = input.destLat && input.destLng
      ? { lat: input.destLat, lng: input.destLng }
      : null;

    if (!pickupCoords) {
      pickupCoords = await geocodeAddress(input.pickupAddress);
    }
    if (!destCoords) {
      destCoords = await geocodeAddress(input.destinationAddress);
    }

    if (!pickupCoords || !destCoords) {
      throw new Error(
        `Could not geocode ${!pickupCoords ? 'pickup' : 'destination'} address. Please enter a more specific UK address.`,
      );
    }

    const distanceKm = await getDrivingDistanceKm(pickupCoords, destCoords);
    if (distanceKm === null) {
      throw new Error(
        'Could not calculate driving route between the two addresses. Please check that both are valid UK postcodes or addresses.',
      );
    }

    return this.calculate({ ...input, distanceKm });
  }

  // ── Core calculation (all monetary values in pence) ───────────────────────────

  async calculate(input: PricingInput): Promise<PricingResult> {
    const settings = await this.getSettings();
    const {
      homeSize,
      moversCount,
      extras,
      distanceKm,
      items = [],
      packingMaterials = [],
      withStorage,
      storageSqft,
      storageDays,
      storageWeeks,
      exactPickupTime,
      stairsFlights = 0,
      parkingDistance = 0,
      promoCode,
      userId,
    } = input;

    // ── 1. Loading time ──────────────────────────────────────────────────────────
    //
    // For FEW_ITEMS (items array provided): loading time is derived from volume.
    // A minimum of 30 mins is always applied so that adding the first item can
    // never *reduce* the estimated duration vs the no-item baseline.
    //
    let loadingTimeMins: number;

    if (items.length > 0) {
      const totalVolume = items.reduce(
        (acc, item) => acc + item.volumeM3 * item.quantity,
        0,
      );
      // Volume-based time, with a 30-min minimum floor
      loadingTimeMins = Math.max(30, totalVolume * PRICING.LOADING_MINS_PER_M3);
    } else if (homeSize) {
      loadingTimeMins = PRICING.MIN_LOADING_BY_SIZE[homeSize];
    } else {
      // No items, no homeSize — minimum booking time (30 min)
      loadingTimeMins = 30;
    }

    loadingTimeMins = Math.max(30, Math.round(loadingTimeMins));

    // ── 2. Travel time ───────────────────────────────────────────────────────────
    const travelTimeMins = Math.round((distanceKm / 30) * 60);
    const totalDurationMins = loadingTimeMins + travelTimeMins;
    const totalHours = totalDurationMins / 60;

    // ── 3. Costs (all in pence to avoid float drift) ─────────────────────────────

    let homeSizeFee = 0;
    if (homeSize === 'ONE') homeSizeFee = settings.fee1Bed;
    else if (homeSize === 'TWO') homeSizeFee = settings.fee2Bed;
    else if (homeSize === 'THREE') homeSizeFee = settings.fee3Bed;
    else if (homeSize === 'FOUR_PLUS') homeSizeFee = settings.fee4Bed;

    const baseCostPence = Math.round(
      totalHours * settings.baseRatePerHour * 100 + homeSizeFee * 100,
    );

    const additionalMoverCostPence =
      moversCount > 1
        ? Math.round(
          totalHours *
          settings.additionalMoverPerHour *
          (moversCount - 1) *
          100,
        )
        : 0;

    // Use fuel rate from DB settings (which defaults to £1.80/mile for the advertised rate).
    const distanceMiles = distanceKm * PRICING.AVG_MILES_PER_KM;
    const fuelCostPence = Math.round(
      distanceMiles * settings.fuelRatePerMile * 100,
    );

    const fullPackingCostPence =
      extras === 'FULL_PACKING'
        ? Math.round(packingPrice(settings.fullPackingCost, homeSize, input.packingTier) * 100)
        : 0;

    const packingMaterialsCostPence = packingMaterials.reduce((acc, m) => {
      let unitPricePence = 0;
      if (m.type === 'MEDIUM_BOX')
        unitPricePence = Math.round(settings.materialMediumBox * 100);
      else if (m.type === 'LARGE_BOX')
        unitPricePence = Math.round(settings.materialLargeBox * 100);
      else if (m.type === 'BUBBLE_WRAP')
        unitPricePence = Math.round(settings.materialBubbleWrap * 100);
      else if (m.type === 'PAPER_ROLL')
        unitPricePence = Math.round(settings.materialPaperRoll * 100);
      else if (m.type === 'TAPE')
        unitPricePence = Math.round(settings.materialTape * 100);
      return acc + unitPricePence * m.quantity;
    }, 0);

    // ── Storage cost ────────────────────────────────────────────────────────────
    // weeklyStorageRatePence = sqft × rate × 100  (integer pence)
    // storageCostPence       = weeklyRate × weeks  OR  dailyRate × days
    let storageCostPence = 0;
    let weeklyStorageRatePence = 0;
    if (withStorage && storageSqft && storageSqft > 0) {
      weeklyStorageRatePence = Math.round(
        storageSqft * settings.storageRatePerSqftPerWeek * 100,
      );
      if (storageWeeks && storageWeeks > 0) {
        storageCostPence = weeklyStorageRatePence * storageWeeks;
      } else if (storageDays && storageDays > 0) {
        // Pro-rate: daily = weekly / 7
        const dailyRatePence = Math.round(weeklyStorageRatePence / 7);
        storageCostPence = dailyRatePence * storageDays;
      } else {
        // Default to 1 week when storage is requested but no duration provided
        storageCostPence = weeklyStorageRatePence;
      }
    }

    // ── Exact-time surcharge ────────────────────────────────────────────────────
    const exactTimeFeePence = exactPickupTime
      ? Math.round((settings.exactTimeFee ?? PRICING_ADDITIONS.EXACT_TIME_FEE) * 100)
      : 0;

    // ── Stairs surcharge (£20 per flight) ──────────────────────────────────────
    const stairsFeePence = stairsFlights > 0 ? stairsFlights * 2000 : 0;

    // ── Parking surcharge (£30 if > 20 metres) ─────────────────────────────────
    const parkingFeePence = parkingDistance > 20 ? 3000 : 0;

    // ── Sum of all cost components (VAT-inclusive gross) ───────────────────────
    const grossComponentsPence =
      baseCostPence +
      additionalMoverCostPence +
      fuelCostPence +
      fullPackingCostPence +
      packingMaterialsCostPence +
      storageCostPence +
      exactTimeFeePence +
      stairsFeePence +
      parkingFeePence;

    // ── Server-side promo discount ─────────────────────────────────────────────
    // The discount is applied to the gross total before VAT extraction.
    // This ensures the frontend never controls the discount percentage.
    let discountAmountPence = 0;
    let appliedPromoCode: string | undefined;
    let promoDisplayText: string | undefined;

    if (promoCode?.trim()) {
      try {
        const code = promoCode.trim().toUpperCase();
        const promo = await this.prisma.promoCode.findUnique({
          where: { code },
          include: { uses: true },
        });

        if (promo && promo.isActive) {
          const now = new Date();
          const expired = promo.expiresAt && promo.expiresAt < now;
          const maxedOut = promo.maxUses && promo.usedCount >= promo.maxUses;
          const alreadyUsed =
            userId && promo.uses.some((u) => u.userId === userId);

          if (!expired && !maxedOut && !alreadyUsed) {
            const grossPounds = grossComponentsPence / 100;
            if (promo.type === 'PERCENT') {
              discountAmountPence = Math.round(
                grossComponentsPence * (promo.value / 100),
              );
              promoDisplayText = `${promo.value}% off`;
            } else {
              // FIXED — cap at gross total
              discountAmountPence = Math.min(
                Math.round(promo.value * 100),
                grossComponentsPence,
              );
              promoDisplayText = `£${promo.value} off`;
            }
            appliedPromoCode = promo.code;
          }
        } else {
          // Try referral code path (10% on first order only)
          const referrer = await this.prisma.user.findUnique({
            where: { referralCode: code },
          });
          if (referrer && (!userId || referrer.id !== userId)) {
            let isFirstOrder = true;
            if (userId) {
              const currentUser = await this.prisma.user.findUnique({
                where: { id: userId },
                include: { bookings: { select: { id: true } } },
              });
              isFirstOrder =
                !currentUser?.referredById &&
                (currentUser?.bookings?.length ?? 0) === 0;
            }
            if (isFirstOrder) {
              discountAmountPence = Math.round(grossComponentsPence * 0.1);
              promoDisplayText = '10% referral discount';
              appliedPromoCode = referrer.referralCode ?? undefined;
            }
          }
        }
      } catch {
        // Promo lookup failure is non-fatal — proceed without discount
      }
    }

    // ── Final totals (VAT-inclusive model) ─────────────────────────────────────
    //
    // totalToPayPence is the VAT-inclusive amount the customer pays.
    // VAT is extracted from the inclusive total:
    //   vatAmountPence  = Math.round(totalToPayPence * 20 / 120)
    //   subtotalPence   = totalToPayPence − vatAmountPence  (ex-VAT)
    //
    // This is the correct UK VAT-inclusive formula and prevents the
    // double-counting bug (total × 0.2 when total already includes VAT).
    const totalToPayPence = Math.max(0, grossComponentsPence - discountAmountPence);
    const vatAmountPence = Math.round(totalToPayPence * 20 / 120);
    const subtotalPence = totalToPayPence - vatAmountPence;

    // ── 4. Format display strings ───────────────────────────────────────────────
    const fmt = (mins: number) => {
      const h = Math.floor(mins / 60);
      const m = mins % 60;
      if (h === 0) return `${m} min`;
      if (m === 0) return `${h} hr`;
      return `${h} hr ${m} min`;
    };

    // Pound values (display only) — always derived from integer pence
    const toPounds = (p: number) => Math.round(p) / 100;

    return {
      distanceKm,

      loadingTimeMins,
      travelTimeMins,
      totalDurationMins,
      loadingTimeDisplay: fmt(loadingTimeMins),
      travelTimeDisplay: fmt(travelTimeMins),
      totalDurationDisplay: fmt(totalDurationMins),

      baseCostPence,
      additionalMoverCostPence,
      fuelCostPence,
      fullPackingCostPence,
      packingMaterialsCostPence,
      storageCostPence,
      exactTimeFeePence,
      stairsFeePence,
      parkingFeePence,
      grossComponentsPence,
      discountAmountPence,
      totalToPayPence,
      vatAmountPence,
      subtotalPence,

      baseCost: toPounds(baseCostPence),
      additionalMoverCost: toPounds(additionalMoverCostPence),
      fuelCost: toPounds(fuelCostPence),
      fullPackingCost: toPounds(fullPackingCostPence),
      packingMaterialsCost: toPounds(packingMaterialsCostPence),
      storageCost: toPounds(storageCostPence),
      exactTimeFee: toPounds(exactTimeFeePence),
      stairsFee: toPounds(stairsFeePence),
      parkingFee: toPounds(parkingFeePence),
      weeklyStoragePrice: toPounds(weeklyStorageRatePence),
      discountAmount: toPounds(discountAmountPence),
      totalToPay: toPounds(totalToPayPence),
      vatAmount: toPounds(vatAmountPence),
      subtotal: toPounds(subtotalPence),
      appliedPromoCode,
      promoDisplayText,
    };
  }
}

import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  MessageBody,
  ConnectedSocket,
  OnGatewayDisconnect, OnGatewayConnection,
} from '@nestjs/websockets';
import { Injectable } from '@nestjs/common';
import { Server, Socket } from 'socket.io';
import { PrismaService } from '../prisma/prisma.service';
import { JwtService } from '@nestjs/jwt';

const STALE_THRESHOLD_MS = 2 * 60 * 1000; // 2 minutes

@Injectable()
@WebSocketGateway({
  cors: {
    origin: [
      ...(process.env.FRONTEND_URL ? [process.env.FRONTEND_URL] : []),
      'https://www.nglob.com',
      'https://nglob.com',
      'https://app.nglob.com',
      'https://manager.nglob.com',
      'https://driver.nglob.com',
      'https://admin.nglob.com',
      'https://ngob.vercel.app',
      'http://localhost:3000',
      'http://localhost:8081',
      'http://nglob.localhost:3000',
      'http://manager.nglob.localhost:3000',
      'http://driver.nglob.localhost:3000',
      'http://admin.nglob.localhost:3000',
      'http://app.nglob.localhost:3000',
    ],
    credentials: true,
  },
  namespace: '/tracking',
})
export class TrackingGateway implements OnGatewayDisconnect, OnGatewayConnection, OnGatewayConnection {
  @WebSocketServer()
  server: Server;

  constructor(private prisma: PrismaService, private jwtService: JwtService) {}

  // ── Client subscribes to a booking room ──────────────────────────────────────
  @SubscribeMessage('subscribe-booking')
  handleSubscribe(
    @MessageBody() data: { bookingId: string },
    @ConnectedSocket() client: Socket,
  ) {
    client.join(`booking:${data.bookingId}`);
    return { event: 'subscribed', bookingId: data.bookingId };
  }

  @SubscribeMessage('unsubscribe-booking')
  handleUnsubscribe(
    @MessageBody() data: { bookingId: string },
    @ConnectedSocket() client: Socket,
  ) {
    client.leave(`booking:${data.bookingId}`);
  }

  async handleConnection(client: Socket) {
    const token = client.handshake.auth?.token;
    if (token) {
      try {
        const decoded = this.jwtService.verify(token);
        client.data.user = decoded;
      } catch (err) {
        // invalid token
      }
    }
  }

  handleDisconnect(client: Socket) {
    // Socket.IO auto-removes from all rooms on disconnect
  }

  @SubscribeMessage('subscribe-manager')
  handleSubscribeManager(@ConnectedSocket() client: Socket) {
    // A2 fix: Verify role
    const user = client.data.user;
    if (!user || (user.role !== 'MANAGER' && user.role !== 'ADMIN')) {
      return { event: 'error', message: 'Unauthorized' };
    }
    client.join('managers');
    return { event: 'subscribed', room: 'managers' };
  }

  @SubscribeMessage('subscribe-driver')
  async handleSubscribeDriver(
    @MessageBody() data: { driverId: string },
    @ConnectedSocket() client: Socket,
  ) {
    // A2 fix: Verify role and ownership
    const user = client.data.user;
    if (!user || user.role !== 'DRIVER') {
      return { event: 'error', message: 'Unauthorized' };
    }
    const driver = await this.prisma.driver.findUnique({ where: { userId: user.id } });
    if (!driver || driver.id !== data.driverId) {
      return { event: 'error', message: 'Forbidden' };
    }
    client.join(`driver:${data.driverId}`);
    return { event: 'subscribed', driverId: data.driverId };
  }

  /**
   * Receives real GPS coordinates from the driver's device.
   * Payload: { driverId, bookingId, lat, lng }
   *
   * On the driver frontend, call:
   *   navigator.geolocation.watchPosition(pos => {
   *     socket.emit('update-location', {
   *       driverId, bookingId,
   *       lat: pos.coords.latitude,
   *       lng: pos.coords.longitude,
   *     });
   *   });
   */
  @SubscribeMessage('update-location')
  async handleLocationUpdate(
    @MessageBody()
    data: {
      driverId: string;
      bookingId: string;
      lat: number;
      lng: number;
    },
  ) {
    const { driverId, bookingId, lat, lng } = data;

    if (
      typeof lat !== 'number' ||
      typeof lng !== 'number' ||
      isNaN(lat) ||
      isNaN(lng) ||
      lat < -90 ||
      lat > 90 ||
      lng < -180 ||
      lng > 180
    ) {
      return { error: 'Invalid coordinates' };
    }

    try {
      // Persist to DB
      await this.prisma.driver.update({
        where: { id: driverId },
        data: {
          currentLat: lat,
          currentLng: lng,
          locationUpdatedAt: new Date(),
        },
      });
    } catch (err) {
      console.warn(
        '[TrackingGateway] Failed to persist location for driver',
        driverId,
        err,
      );
    }

    // Broadcast to booking room and all managers
    this.broadcastDriverLocation(bookingId, { lat, lng, status: 'ONLINE' });

    return { ok: true };
  }

  // ── Broadcast helpers ─────────────────────────────────────────────────────────

  broadcastToManagers(event: string, payload?: any) {
    this.server.to('managers').emit(event, payload);
  }

  broadcastToDriver(driverId: string, event: string, payload?: any) {
    this.server.to(`driver:${driverId}`).emit(event, payload);
  }

  broadcastDriverLocation(
    bookingId: string,
    payload: {
      lat: number;
      lng: number;
      status: string;
      estimatedArrival?: string;
    },
  ) {
    const data = { bookingId, ...payload, timestamp: new Date().toISOString() };
    this.server.to(`booking:${bookingId}`).emit('driver-location', data);
    this.server.to('managers').emit('driver-location', data);
  }

  /**
   * Check staleness and broadcast OFFLINE status for a driver.
   * Call this from a scheduled job or when a client polls for location.
   */
  async broadcastDriverStatusIfStale(driverId: string, bookingId: string) {
    try {
      const driver = await this.prisma.driver.findUnique({
        where: { id: driverId },
        select: { currentLat: true, currentLng: true, locationUpdatedAt: true },
      });

      if (!driver?.locationUpdatedAt) return;

      const isStale =
        Date.now() - new Date(driver.locationUpdatedAt).getTime() >
        STALE_THRESHOLD_MS;

      if (isStale) {
        this.broadcastDriverLocation(bookingId, {
          lat: driver.currentLat ?? 0,
          lng: driver.currentLng ?? 0,
          status: 'OFFLINE',
        });
      }
    } catch (err) {
      console.warn(
        '[TrackingGateway] broadcastDriverStatusIfStale error:',
        err,
      );
    }
  }
}
